INSERT INTO _n1_b5_guard_0106(ok) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM japanese_jlpt_daily_sessions s JOIN japanese_jlpt_study_plans p ON p.id=s.plan_id WHERE p.plan_code='N1_2027_JUL' AND s.study_date BETWEEN '2026-11-26' AND '2026-12-09' AND (s.status <> 'not_started' OR s.started_at IS NOT NULL OR s.completed_at IS NOT NULL)) THEN 1 ELSE 0 END;
INSERT INTO _n1_b5_words_0106(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-2739','2026-11-26','煩わしい','わずらわしい','번거롭다; 성가시다; 귀찮다','面倒で手間がかかり、わずらいを感じる。','毎回同じ情報を入力するのは煩わしい。','매번 같은 정보를 입력하는 것은 번거롭다.'),
('n1-2751','2026-11-26','鈍る','なまる','무뎌지다; 둔해지다; 능력이 떨어지다','刃・感覚・能力などの鋭さが失われる。','長く練習しないと感覚が鈍る。','오랫동안 연습하지 않으면 감각이 둔해진다.'),
('n1-2752','2026-11-26','映える','はえる','돋보이다; 빛나다; 잘 어울리다','周囲との調和や対比によって美しく目立つ。','青空に白い建物がよく映える。','푸른 하늘에 흰 건물이 잘 돋보인다.'),
('n1-2754','2026-11-26','しなやか','しなやか','유연하다; 부드럽고 탄력 있다','柔らかく、よく曲がって折れにくいさま。また、動きが柔軟で美しいさま。','猫はしなやかな動きで塀の上に飛び乗った。','고양이는 유연한 움직임으로 담 위에 뛰어올랐다.'),
('n1-2767','2026-11-26','情け深い','なさけぶかい','인정이 많다; 자비롭다','人に対する思いやりや慈しみの気持ちが強い。','彼は困っている人を放っておけない情け深い人だ。','그는 곤란한 사람을 그냥 지나치지 못하는 인정 많은 사람이다.'),
('n1-2793','2026-11-26','図々しい','ずうずうしい','뻔뻔하다; 염치없다','恥ずかしがらず、遠慮なく厚かましく振る舞う。','初対面でそこまで頼むのは少し図々しい。','초면에 거기까지 부탁하는 건 조금 뻔뻔하다.'),
('n1-2796','2026-11-26','ずばり','ずばり','딱 잘라; 정곡을 찔러; 단도직입적으로','要点を外さず、はっきりと言ったり当てたりするさま。','彼は問題の原因をずばり指摘した。','그는 문제의 원인을 정확히 짚었다.'),
('n1-2740','2026-11-26','群がる','むらがる','떼 지어 몰려들다; 무리를 이루어 모이다','多くの人・動物などが一か所に集まる。','餌の周りに鳥が群がっていた。','먹이 주변에 새들이 떼 지어 몰려 있었다.'),
('n1-2742','2026-11-26','躓く','つまずく','발이 걸려 넘어질 뻔하다; 좌절하다; 일이 막히다','足が物に引っ掛かってよろける。また、物事の途中で失敗して行き詰まる。','最初の設計段階で躓き、計画を見直した。','초기 설계 단계에서 막혀 계획을 재검토했다.'),
('n1-2744','2026-11-26','打ち合わせる','うちあわせる','협의하다; 사전 조율하다','仕事などについて前もって相談し、内容や手順を確認する。','明日の発表内容を事前に打ち合わせた。','내일 발표 내용을 사전에 협의했다.'),
('n1-2758','2026-11-26','据え付ける','すえつける','설치하다; 고정해서 달다','機械・設備などを動かないように一定の場所へ取り付ける。','工場に新しい機械を据え付けた。','공장에 새 기계를 설치했다.'),
('n1-2772','2026-11-26','綻びる','ほころびる','솔기가 터지다; 벌어지다; 미소가 번지다','縫い目などがほどけて開く。また、つぼみや表情が開くようにほぐれる。','古いシャツの袖口が綻びてきた。','낡은 셔츠 소맷단의 솔기가 터지기 시작했다.'),
('n1-2773','2026-11-26','ぼやける','ぼやける','흐려지다; 흐릿해지다; 초점이 모호해지다','形・色・輪郭などがはっきりしなくなる。','カメラが動いて写真が少しぼやけた。','카메라가 움직여 사진이 조금 흐릿해졌다.'),
('n1-2777','2026-11-26','しくじる','しくじる','실수하다; 일을 망치다; 실패하다','やり方を誤って失敗する。','大事な場面でしくじってしまった。','중요한 순간에 실수하고 말았다.'),
('n1-2803','2026-11-26','剥げる','はげる','벗겨지다; 칠이 벗겨지다; 색이 바래다','表面の塗装・皮などが取れる。また、色が薄くなる。','古い椅子の塗装がところどころ剥げている。','낡은 의자의 칠이 군데군데 벗겨져 있다.'),
('n1-2831','2026-11-26','怒る','いかる','화내다; 분노하다','強い怒りを感じる。また、波などが荒れ立つこともいう。','不正を知った彼は激しく怒った。','부정을 알게 된 그는 크게 분노했다.'),
('n1-2839','2026-11-26','意気込む','いきごむ','의욕에 차다; 벼르다; 기세등등하다','何かをしようと強く張り切り、気持ちを高める。','彼は新しい仕事を成功させようと意気込んでいる。','그는 새 일을 성공시키려고 의욕에 차 있다.'),
('n1-2840','2026-11-26','活ける','いける','꽃을 꽂다; 꽃꽂이하다','花や枝を器に美しく配置する。','玄関に季節の花を活けた。','현관에 계절 꽃을 꽂았다.'),
('n1-2859','2026-11-26','納まる','おさまる','들어가다; 수납되다; 납부되다; 해결되다','ある場所や範囲に収まる。また、金品が納入される。','荷物はすべて棚に納まった。','짐은 모두 선반에 들어갔다.'),
('n1-2864','2026-11-26','省みる','かえりみる','돌이켜보다; 반성하다','自分の言動や過去を振り返り、よく考える。','失敗の原因を省みて次に生かす。','실패 원인을 되돌아보고 다음에 살린다.'),
('n1-2797','2026-11-27','馴れ馴れしい','なれなれしい','지나치게 친한 척하다; 스스럼없다; 친한 체하다','まだ親しくない相手に、必要以上に親しげな態度を取る。','初対面なのに馴れ馴れしい話し方をされて戸惑った。','초면인데도 지나치게 친한 척하는 말투라 당황했다.'),
('n1-2810','2026-11-27','是非とも','ぜひとも','꼭; 반드시; 부디','強い希望・依頼を表し、何としてもという気持ちを示す。','次回の会議には是非とも参加してください。','다음 회의에는 꼭 참석해 주세요.'),
('n1-2812','2026-11-27','見せびらかす','みせびらかす','과시하다; 자랑해 보이다','自慢するために人にわざと見せつける。','高価な時計を見せびらかすような態度は好まれない。','비싼 시계를 과시하는 듯한 태도는 좋게 보이지 않는다.'),
('n1-2816','2026-11-27','長々','ながなが','장황하게; 오래도록; 길게','時間・文章・話などが必要以上に長く続くさま。','長々と説明してしまい、申し訳ありません。','장황하게 설명해서 죄송합니다.'),
('n1-2833','2026-11-27','粉々','こなごな','산산조각; 산산이','非常に細かく砕けた状態。','落とした皿が粉々に割れた。','떨어뜨린 접시가 산산조각 났다.'),
('n1-2846','2026-11-27','厭らしい','いやらしい','불쾌하다; 야하다; 징그럽다; 노골적이다','不快で感じが悪い。また、性的に露骨で品がないこともいう。','人の弱みに付け込むような厭らしいやり方は嫌いだ。','남의 약점을 이용하는 불쾌한 방식은 싫다.'),
('n1-2855','2026-11-27','大ざっぱ','おおざっぱ','대충이다; 대략적이다; 세세하지 않다','細部にこだわらず、大体で物事を扱うさま。','まずは大ざっぱな予定を決めよう。','우선 대략적인 일정을 정하자.'),
('n1-2869','2026-11-27','可愛がる','かわいがる','귀여워하다; 아끼다','かわいいと思って大切にする。','祖父は孫をとても可愛がっている。','할아버지는 손주를 매우 귀여워하신다.'),
('n1-2922','2026-11-27','尚','なお','더욱; 여전히; 또한','以前の状態が続くさま。また、さらに付け加えるさま。','雨はやんだが、風はなお強い。','비는 그쳤지만 바람은 여전히 강하다.'),
('n1-2930','2026-11-27','恥じらう','はじらう','수줍어하다; 부끄러워하다','恥ずかしそうな態度を見せる。','彼女は少し恥じらいながら答えた。','그녀는 조금 수줍어하며 대답했다.'),
('n1-2931','2026-11-27','ばてる','ばてる','지치다; 기진맥진하다','疲れ切って力がなくなる。','暑さで完全にばててしまった。','더위 때문에 완전히 지쳐 버렸다.'),
('n1-2972','2026-11-27','正しく','まさしく','바로; 틀림없이; 과연','疑いなく、まさにその通りであるさま。','これはまさしく私が探していた資料だ。','이것이 바로 내가 찾고 있던 자료다.'),
('n1-2995','2026-11-27','汚れる','けがれる','더럽혀지다; 오염되다; 명예가 훼손되다','清らかさ・純粋さ・名誉などが失われる。','不正によって組織の名誉が汚れた。','부정행위로 조직의 명예가 더럽혀졌다.'),
('n1-1306','2026-11-27','彼方','あちら','저쪽; 저곳; 저분','話し手・聞き手から離れた場所・方向・人を丁寧に指す語。','受付はあちらの建物の一階にございます。','접수처는 저쪽 건물 1층에 있습니다.'),
('n1-2866','2026-11-27','兼ねて','かねて','겸하여; 동시에; 예전부터','二つ以上の事柄を同時に行うさま。また、以前から。','視察を兼ねて現地を訪れた。','시찰을 겸해 현지를 방문했다.'),
('n1-2870','2026-11-27','気障','きざ','잘난 체하는; 멋을 부리는; 느끼한','気取っていて、いやみに感じられるさま。','彼の気障な台詞に皆が苦笑した。','그의 잘난 체하는 대사에 모두가 쓴웃음을 지었다.'),
('n1-2898','2026-11-27','添う','そう','따르다; 부응하다; 함께하다','そばに付き従う。また、希望・期待などにかなう。','利用者の希望に添う形で制度を見直した。','이용자의 희망에 부응하는 형태로 제도를 재검토했다.'),
('n1-2904','2026-11-27','貴い','たっとい','귀하다; 존귀하다; 소중하다','非常に価値が高く、尊ぶべきである。','人の命は何よりも貴い。','사람의 생명은 무엇보다 소중하다.'),
('n1-2919','2026-11-27','留める','とどめる','멈추다; 머물게 하다; 남겨 두다','動き・進行を止める。また、ある状態・場所に残す。','被害を最小限に留める必要がある。','피해를 최소한으로 억제할 필요가 있다.'),
('n1-2923','2026-11-27','生温い','なまぬるい','미지근하다; 미적지근하다; 태도가 안이하다','少し温かく、熱くも冷たくもない。また、態度などが厳しさに欠ける。','生温い水ではなく冷たい水が飲みたい。','미지근한 물 말고 차가운 물을 마시고 싶다.');
INSERT INTO _n1_b5_words_0106(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-2927','2026-11-28','拝啓','はいけい','삼가 아룁니다; 존경하는 ~께','手紙の冒頭に用いる改まった挨拶語。','拝啓　時下ますますご清栄のこととお喜び申し上げます。','삼가 아룁니다. 귀사의 무궁한 발전을 기원합니다.'),
('n1-2938','2026-11-28','一人でに','ひとりでに','저절로; 자연히','人が手を加えなくても自然にそうなるさま。','しばらくすると扉が一人でに開いた。','잠시 후 문이 저절로 열렸다.'),
('n1-2939','2026-11-28','冷やかす','ひやかす','놀리다; 야유하다; 구경만 하다','からかったり、買う気もなく店を見て回ったりする。','友人の失敗をいつまでも冷やかすのはよくない。','친구의 실수를 계속 놀리는 것은 좋지 않다.'),
('n1-2946','2026-11-28','真に','まことに','참으로; 정말로; 진실로','本当に。心から。','ご協力いただき、真にありがとうございます。','협력해 주셔서 진심으로 감사합니다.'),
('n1-2947','2026-11-28','真っ二つ','まっぷたつ','정확히 둘로; 두 동강','完全に二つに分かれること。','板が真っ二つに割れた。','판자가 정확히 두 동강 났다.'),
('n1-2989','2026-11-28','盛る','さかる','번성하다; 한창이다; 동물이 발정하다','勢いが盛んになる。繁栄する。また、動物が発情する。','春になると多くの花が盛る。','봄이 되면 많은 꽃이 한창 핀다.'),
('n1-2992','2026-11-28','整然','せいぜん','정연함; 질서정연함','秩序正しく、きちんと整っているさま。','資料が棚に整然と並べられている。','자료가 선반에 질서정연하게 놓여 있다.'),
('n1-0702','2026-11-28','収支','しゅうし','수지; 수입과 지출','収入と支出。また、その差し引きの状態。','事業の収支を毎月確認し、赤字が続く部門の原因を分析している。','사업의 수지를 매달 확인하고 적자가 계속되는 부문의 원인을 분석하고 있다.'),
('n1-0703','2026-11-28','展望','てんぼう','전망; 앞날에 대한 예상; 조망','遠くまで見渡すこと。また、将来の成り行きについて見通すこと。','報告書では市場の現状だけでなく、今後五年間の展望についても述べている。','보고서에서는 시장의 현황뿐 아니라 향후 5년의 전망에 대해서도 서술하고 있다.'),
('n1-0705','2026-11-28','独創','どくそう','독창; 새로운 것을 독자적으로 만들어 냄','他人のまねではなく、自分自身の考えで新しいものを生み出すこと。','既存技術を組み合わせただけでなく、独創的な発想を加えた点が高く評価された。','기존 기술을 조합한 것뿐 아니라 독창적인 발상을 더한 점이 높게 평가되었다.'),
('n1-2530','2026-11-28','執着','しゅうじゃく','집착; 미련; 한 대상에 얽매임','一つの物事に心を強くとらわれ、そこから離れられないこと。','過去の成功に執着しすぎると、新しい変化を受け入れにくくなる。','과거의 성공에 지나치게 집착하면 새로운 변화를 받아들이기 어려워진다.'),
('n1-0713','2026-11-28','心情','しんじょう','심정; 마음속 감정','心の中に抱いている感情・思い。','被害者の心情に配慮し、取材内容の公開範囲を慎重に決めた。','피해자의 심정을 배려해 취재 내용의 공개 범위를 신중히 정했다.'),
('n1-0714','2026-11-28','語彙','ごい','어휘; 단어의 총체','ある言語・分野・個人などが用いる単語の総体。','専門分野の文章を正確に読むには、一般語だけでなく専門語彙も必要になる。','전문 분야의 글을 정확히 읽으려면 일반어뿐 아니라 전문 어휘도 필요하다.'),
('n1-0722','2026-11-28','終始','しゅうし','시종; 처음부터 끝까지','物事の始めから終わりまで一貫していること。また、その間ずっと。','会議中、彼は終始冷静な態度を崩さなかった。','회의 내내 그는 시종 냉정한 태도를 잃지 않았다.'),
('n1-0723','2026-11-28','人柄','ひとがら','인품; 사람됨; 성품','言動などから感じ取られる、その人の性質・品性・人となり。','面接では経歴だけでなく、誠実な人柄も高く評価された。','면접에서는 경력뿐 아니라 성실한 인품도 높이 평가되었다.'),
('n1-0729','2026-11-28','合致','がっち','합치; 일치','意見・条件・目的などが食い違わず、ぴったり一致すること。','提案内容が顧客の要望と合致しているか、契約前に確認した。','제안 내용이 고객 요구와 일치하는지 계약 전에 확인했다.'),
('n1-0733','2026-11-28','中傷','ちゅうしょう','중상; 근거 없는 비방','根拠のない悪口などで他人の名誉や信用を傷つけること。','匿名であっても、他人を中傷する投稿は許されない。','익명이라도 타인을 중상하는 게시물은 허용되지 않는다.'),
('n1-0738','2026-11-28','再発','さいはつ','재발','いったん収まった病気・事故・問題などが、再び起こること。','同じ障害の再発を防ぐため、原因分析と手順の見直しを行った。','같은 장애의 재발을 막기 위해 원인 분석과 절차 재검토를 실시했다.'),
('n1-0743','2026-11-28','調停','ちょうてい','조정; 중재','争っている当事者の間に入り、話し合いによる解決・合意を図ること。','双方の主張が対立したため、第三者による調停が行われた。','양측의 주장이 대립해 제3자에 의한 조정이 이루어졌다.'),
('n1-0750','2026-11-28','土台','どだい','토대; 기반; 기초','建物などを支える基礎部分。また、物事が成立するための基礎・基盤。','基礎研究の積み重ねが、新しい技術を生み出す土台になる。','기초 연구의 축적이 새로운 기술을 만들어 내는 토대가 된다.'),
('n1-0753','2026-11-29','異動','いどう','인사이동; 보직 변경','職場で所属・役職・勤務地などが変わること。','四月の人事異動で、営業部から企画部へ移ることになった。','4월 인사이동으로 영업부에서 기획부로 옮기게 되었다.'),
('n1-0758','2026-11-29','応急','おうきゅう','응급; 임시 대응','急場をしのぐため、とりあえず必要な処置をすること。','負傷者には現場で応急処置を施した後、病院へ搬送した。','부상자에게 현장에서 응급처치를 한 뒤 병원으로 이송했다.'),
('n1-0761','2026-11-29','暗示','あんじ','암시; 넌지시 알려 줌','直接はっきり言わずに、ある事柄をそれとなく示すこと。','上司の発言は、組織改編が近いことを暗示しているように聞こえた。','상사의 발언은 조직 개편이 가깝다는 것을 암시하는 듯 들렸다.'),
('n1-0769','2026-11-29','断言','だんげん','단언; 장담','確信を持って、はっきりと言い切ること。','十分な証拠がない以上、原因が一つだけだと断言することはできない。','충분한 증거가 없는 이상 원인이 하나뿐이라고 단언할 수는 없다.'),
('n1-0790','2026-11-29','転落','てんらく','추락; 전락','高い所から落ちること。また、地位・状態などが悪い方向へ急に下がること。','会社は主力商品の不振をきっかけに赤字へ転落した。','회사는 주력 상품 부진을 계기로 적자로 전락했다.'),
('n1-0791','2026-11-29','心中','しんじゅう','동반자살; 함께 자살함','二人以上の者が、申し合わせて一緒に自殺すること。','その古典作品は、社会に追い詰められた男女の心中を題材にしている。','그 고전 작품은 사회에 몰린 남녀의 동반자살을 소재로 하고 있다.'),
('n1-0792','2026-11-29','補強','ほきょう','보강; 강도를 높임','不足している部分を補い、強度・能力などをさらに強くすること。','地震対策として、古い建物の柱を補強する工事が進められている。','지진 대책으로 오래된 건물의 기둥을 보강하는 공사가 진행되고 있다.'),
('n1-0798','2026-11-29','増強','ぞうきょう','증강; 강화','人員・設備・能力などを増やして、全体の力を強くすること。','問い合わせの増加に対応するため、サポート要員を増強した。','문의 증가에 대응하기 위해 지원 인력을 증강했다.'),
('n1-0800','2026-11-29','打開','だかい','타개; 돌파구를 엶','行き詰まった困難な状況を切り開き、解決への道を作ること。','売上低迷を打開するため、会社は新しい市場への進出を決めた。','매출 침체를 타개하기 위해 회사는 새로운 시장 진출을 결정했다.'),
('n1-0802','2026-11-29','創刊','そうかん','창간','新聞・雑誌などの定期刊行物を新しく発行し始めること。','その雑誌は創刊から百年を迎え、記念号を発売した。','그 잡지는 창간 100주년을 맞아 기념호를 발매했다.'),
('n1-0807','2026-11-29','一変','いっぺん','일변; 완전히 바뀜','状態・雰囲気・状況などがすっかり変わること。また、変えること。','新しい責任者が就任してから、職場の雰囲気は一変した。','새 책임자가 취임한 뒤 직장 분위기가 완전히 바뀌었다.'),
('n1-0811','2026-11-29','戯曲','ぎきょく','희곡','舞台で上演することを目的に、人物のせりふや動作を中心として書かれた文学作品。','この戯曲は百年以上たった今も世界各地で上演されている。','이 희곡은 100년 이상 지난 지금도 세계 각지에서 공연되고 있다.'),
('n1-0813','2026-11-29','外相','がいしょう','외무상; 외교 담당 장관','外交を担当する大臣。『外務大臣』の略称。','両国の外相は会談し、安全保障と経済協力について意見を交わした。','양국 외무상은 회담을 열어 안보와 경제 협력에 대해 의견을 나눴다.'),
('n1-0818','2026-11-29','不振','ふしん','부진; 침체','成績・売上・活動などの勢いが上がらず、望ましい状態に達していないこと。','主力事業の不振が続き、会社は収益構造の見直しを迫られている。','주력 사업의 부진이 계속되어 회사는 수익 구조 재검토를 요구받고 있다.'),
('n1-0826','2026-11-29','重宝','じゅうほう','매우 유용함; 소중히 여김','便利で役に立つものとして大切に使うこと。また、非常に便利で役立つさま。','この小型の翻訳端末は海外出張でとても重宝している。','이 소형 번역 단말기는 해외 출장에서 매우 유용하게 쓰고 있다.'),
('n1-0827','2026-11-29','引き分け','ひきわけ','무승부','試合・勝負で、双方の得点や成績が同じで勝敗が決まらないこと。','試合は延長戦でも決着がつかず、引き分けに終わった。','경기는 연장전에서도 승부가 나지 않아 무승부로 끝났다.'),
('n1-0830','2026-11-29','全滅','ぜんめつ','전멸; 전부 소멸함','集団・生物・設備などが残らず失われたり、すべて駄目になったりすること。','長雨の影響で畑の作物がほぼ全滅し、農家は大きな被害を受けた。','장마의 영향으로 밭의 작물이 거의 전멸해 농가가 큰 피해를 입었다.'),
('n1-2940','2026-11-29','消耗','しょうこう','소모; 닳아 없어짐; 기력이 쇠함','物や力などを使って減らすこと。また、使ううちに減ったり弱ったりすること。','長時間の作業で体力を大きく消耗した。','장시간 작업으로 체력을 크게 소모했다.'),
('n1-0839','2026-11-29','吟味','ぎんみ','음미; 꼼꼼히 검토함','内容・品質・条件などを細かく調べ、十分に検討すること。','複数の案を十分に吟味したうえで、最も現実的な方法を選んだ。','여러 안을 충분히 검토한 뒤 가장 현실적인 방법을 선택했다.'),
('n1-0845','2026-11-29','痛感','つうかん','통감; 절실히 느낌','ある事実・重要性などを、身にしみて強く感じること。','今回の失敗を通して、事前確認の重要性を改めて痛感した。','이번 실패를 통해 사전 확인의 중요성을 다시 절실히 느꼈다.');
INSERT INTO _n1_b5_words_0106(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0853','2026-11-30','口頭','こうとう','구두; 말로 함','書面ではなく、口で話して伝えること。','重要な変更は口頭だけで済ませず、必ず記録を残してください。','중요한 변경은 구두로만 끝내지 말고 반드시 기록을 남겨 주세요.'),
('n1-0854','2026-11-30','是正','ぜせい','시정; 바로잡음','誤り・不公平・不適切な状態を正しく改めること。','監査で指摘された問題を是正するため、業務手順を変更した。','감사에서 지적된 문제를 시정하기 위해 업무 절차를 변경했다.'),
('n1-0856','2026-11-30','自我','じが','자아','自分自身を他者と区別し、一個の存在として意識する心・自己意識。','成長するにつれて自我が芽生え、自分の考えを強く主張するようになる。','성장하면서 자아가 싹트고 자신의 생각을 강하게 주장하게 된다.'),
('n1-0858','2026-11-30','賛美','さんび','찬미; 높이 칭송함','優れたもの・美しいもの・価値あるものを褒めたたえること。','この詩は自然の美しさを賛美すると同時に、人間の弱さも描いている。','이 시는 자연의 아름다움을 찬미하는 동시에 인간의 나약함도 그리고 있다.'),
('n1-0859','2026-11-30','代弁','だいべん','대변; 대신 말함','本人・集団に代わって、その考え・要求・気持ちなどを述べること。','代表者は現場の職員の意見を代弁して、経営陣に改善を求めた。','대표자는 현장 직원의 의견을 대변해 경영진에 개선을 요구했다.'),
('n1-0864','2026-11-30','反感','はんかん','반감; 반발감','相手の言動・考えなどに対して感じる反発・不快な気持ち。','一方的な説明は住民の反感を招くおそれがある。','일방적인 설명은 주민의 반감을 살 우려가 있다.'),
('n1-0871','2026-11-30','対比','たいひ','대비; 대조','二つ以上のものを並べて比べ、違い・特徴を明確にすること。','都市と農村の生活を対比することで、地域ごとの課題が見えてくる。','도시와 농촌의 생활을 대비하면 지역별 과제가 보인다.'),
('n1-0879','2026-11-30','沿線','えんせん','철도 노선 연변; 노선 주변','鉄道路線に沿った地域。','新駅の開業をきっかけに、沿線の住宅開発が進んでいる。','새 역 개통을 계기로 철도 노선 주변의 주택 개발이 진행되고 있다.'),
('n1-0880','2026-11-30','仕上がり','しあがり','완성된 상태; 마무리 품질','仕事・製品・作品などが完成したときの出来具合・状態。','試作品は機能だけでなく、外観の仕上がりも高く評価された。','시제품은 기능뿐 아니라 외관의 마무리 품질도 높게 평가되었다.'),
('n1-0882','2026-11-30','初版','しょはん','초판','書籍などが最初に印刷・発行された版。','この作品の初版は現在では入手が難しく、古書市場で高値が付いている。','이 작품의 초판은 현재 구하기 어려워 고서 시장에서 높은 가격이 붙어 있다.'),
('n1-0886','2026-11-30','両立','りょうりつ','양립; 두 가지를 함께 성립시킴','二つの物事を、どちらも損なわず同時に成り立たせること。','仕事と育児を両立できるよう、柔軟な勤務制度が導入された。','일과 육아를 양립할 수 있도록 유연한 근무 제도가 도입되었다.'),
('n1-0899','2026-11-30','調印','ちょういん','조인; 서명 체결','条約・協定などの正式な文書に、当事者が署名すること。','両国は協定書に調印し、来月から新しい制度を開始する。','양국은 협정서에 조인하고 다음 달부터 새 제도를 시작한다.'),
('n1-0903','2026-11-30','対談','たいだん','대담; 서로 마주 보고 이야기함','二人ほどの人が、特定のテーマについて向かい合って話し合うこと。','雑誌には研究者と起業家の対談が掲載されている。','잡지에는 연구자와 기업가의 대담이 실려 있다.'),
('n1-0905','2026-11-30','共鳴','きょうめい','공명; 깊이 공감함','物理的に同じ振動数で響き合うこと。また比喩的に、他人の思想・感情に強く共感すること。','若い世代の多くが、その作家の率直な主張に共鳴した。','젊은 세대의 많은 사람이 그 작가의 솔직한 주장에 깊이 공감했다.'),
('n1-0915','2026-11-30','期日','きじつ','기일; 정해진 날짜','あらかじめ定められた日。ある事を行う期限・予定の日。','提出期日を過ぎた書類は原則として受け付けられない。','제출 기일이 지난 서류는 원칙적으로 접수되지 않는다.'),
('n1-0918','2026-11-30','平常','へいじょう','평상시; 평소','特別な出来事がない、いつもどおりの状態・時。','災害時にも平常どおり対応できるよう、定期的に訓練を行っている。','재해 시에도 평상시처럼 대응할 수 있도록 정기적으로 훈련하고 있다.'),
('n1-0920','2026-11-30','弾力','だんりょく','탄력; 유연성','力を加えると変形し、力を除くともとに戻ろうとする性質。また比喩的に、状況に応じて柔軟に対応する力。','制度を運用する際には、例外にも対応できる弾力性が求められる。','제도를 운용할 때는 예외에도 대응할 수 있는 유연성이 요구된다.'),
('n1-0923','2026-11-30','内訳','うちわけ','내역; 세부 구성','合計額・総数などを、項目ごとに分けた詳しい内容。','見積書には費用の内訳を項目ごとに明記してください。','견적서에는 비용 내역을 항목별로 명확히 적어 주세요.'),
('n1-0933','2026-11-30','売れ行き','うれゆき','판매 추이; 판매 실적','商品がどの程度売れているかという状況・勢い。','新製品は発売直後から売れ行きが好調で、追加生産が決まった。','신제품은 출시 직후부터 판매 실적이 좋아 추가 생산이 결정됐다.'),
('n1-0936','2026-11-30','増進','ぞうしん','증진; 더욱 향상시킴','能力・健康・利益などをさらに高め、進ませること。','社員の健康増進を目的に、運動習慣を支援する制度を導入した。','직원의 건강 증진을 목적으로 운동 습관을 지원하는 제도를 도입했다.'),
('n1-0967','2026-12-01','所謂','いわゆる','이른바; 소위','世間で一般にそのように呼ばれている、という意味を表す連体語。','これは所謂『成功例』だけを集めた資料であり、失敗例は含まれていない。','이것은 이른바 ‘성공 사례’만 모은 자료로 실패 사례는 포함돼 있지 않다.'),
('n1-1009','2026-12-01','意図','いと','의도; 목적','何かをしようとする考え・ねらい。','発言の一部だけを切り取ると、本人の意図とは異なる意味に受け取られかねない。','발언의 일부만 떼어 내면 본인의 의도와 다른 의미로 받아들여질 수 있다.'),
('n1-1030','2026-12-01','犠牲','ぎせい','희생; 희생자','ある目的のために生命・利益などを失うこと。また、事故・災害などで被害を受けた人。','安全性を無視して利益だけを優先すれば、利用者が犠牲になりかねない。','안전성을 무시하고 이익만 우선하면 이용자가 희생될 수 있다.'),
('n1-1036','2026-12-01','栽培','さいばい','재배','植物・作物を植えて育てること。','この地域では気候を生かして高品質なぶどうを栽培している。','이 지역에서는 기후를 살려 고품질 포도를 재배하고 있다.'),
('n1-1046','2026-12-01','排除','はいじょ','배제; 제거','不要・不適切とみなしたものを取り除き、外へ押し出すこと。','特定の立場の人だけを議論から排除してはならない。','특정 입장의 사람만 논의에서 배제해서는 안 된다.'),
('n1-1053','2026-12-01','消息','しょうそく','소식; 행방; 근황','離れている人の近況・行方についての知らせ。','事故の後、数日間消息が分からなかった登山者が無事発見された。','사고 후 며칠간 소식이 끊겼던 등산객이 무사히 발견됐다.'),
('n1-1091','2026-12-01','収容','しゅうよう','수용; 시설 등에 넣음','人・物を一定の施設・場所の中に入れること。また、そこに入れられる容量。','避難所には最大で五百人を収容できる設備が整っている。','대피소에는 최대 500명을 수용할 수 있는 설비가 갖춰져 있다.'),
('n1-1098','2026-12-01','辞職','じしょく','사직; 직책에서 물러남','自分の意思で職務・役職を辞めること。','責任を取る形で社長が辞職する意向を表明した。','책임을 지는 형태로 사장이 사직 의사를 밝혔다.'),
('n1-1104','2026-12-01','衝撃','しょうげき','충격; 쇼크','物体に急激に加わる強い力。また、予想外の出来事によって心に受ける強い刺激。','突然の発表は業界全体に大きな衝撃を与えた。','갑작스러운 발표는 업계 전체에 큰 충격을 주었다.'),
('n1-1105','2026-12-01','孤児','こじ','고아','両親または保護者を失い、養育する人がいない子ども。','その団体は戦争で孤児となった子どもたちを支援している。','그 단체는 전쟁으로 고아가 된 아이들을 지원하고 있다.'),
('n1-1108','2026-12-01','仕掛け','しかけ','장치; 구조; 꾸민 수단','目的を達成するために設けられた装置・工夫・仕組み。また、人を誘導するためのたくらみ。','展示には子どもが触れると音が鳴る仕掛けが施されている。','전시물에는 아이가 만지면 소리가 나는 장치가 마련되어 있다.'),
('n1-1109','2026-12-01','負傷','ふしょう','부상; 다침','事故・戦闘・スポーツなどで体に傷を負うこと。','事故で三人が負傷し、病院に搬送された。','사고로 세 명이 부상을 입어 병원으로 이송되었다.'),
('n1-1119','2026-12-01','閉鎖','へいさ','폐쇄; 닫음','施設・道路・組織などを閉じて利用・活動できない状態にすること。','老朽化した橋は安全確認が終わるまで一時閉鎖された。','노후화한 다리는 안전 확인이 끝날 때까지 일시 폐쇄되었다.'),
('n1-1123','2026-12-01','妊娠','にんしん','임신','女性・雌の体内に胎児が宿り、育っている状態になること。','妊娠中は体調の変化に合わせて無理のない生活を送ることが大切だ。','임신 중에는 몸 상태 변화에 맞춰 무리하지 않는 생활을 하는 것이 중요하다.'),
('n1-1124','2026-12-01','織物','おりもの','직물; 짠 천','縦糸と横糸を組み合わせて織った布。','この地域では伝統的な織物の技術が今も受け継がれている。','이 지역에서는 전통 직물 기술이 지금도 계승되고 있다.'),
('n1-1128','2026-12-01','襲撃','しゅうげき','습격; 급작스러운 공격','相手・場所などを不意に襲って攻撃すること。','警備当局は施設への襲撃に備えて警戒を強化した。','경비 당국은 시설 습격에 대비해 경계를 강화했다.'),
('n1-1129','2026-12-01','見込み','みこみ','가망; 전망; 예상','将来そうなる可能性・期待。また、あらかじめ立てた予想。','部品の調達が進み、予定どおり納品できる見込みだ。','부품 조달이 진행되어 예정대로 납품할 전망이다.'),
('n1-1130','2026-12-01','削減','さくげん','삭감; 감축','数量・費用・人員・排出量などを減らすこと。','電力消費を削減するため、設備の運転方法を見直した。','전력 소비를 줄이기 위해 설비 운전 방식을 재검토했다.'),
('n1-1136','2026-12-01','避難','ひなん','피난; 대피','災害・事故・戦争などの危険を避け、安全な場所へ移動すること。','警報が鳴ったら、案内に従って速やかに避難してください。','경보가 울리면 안내에 따라 신속히 대피해 주세요.'),
('n1-1148','2026-12-01','詐欺','さぎ','사기; 속임수','人をだまして金品・利益などを得ること。','不審な請求メールは詐欺の可能性があるため、リンクを開かないでください。','수상한 청구 메일은 사기일 가능성이 있으므로 링크를 열지 마세요.');
INSERT INTO _n1_b5_words_0106(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1151','2026-12-02','小売','こうり','소매','商品を最終的な消費者に少量ずつ販売すること。','原材料価格の上昇が小売価格にも反映され始めた。','원재료 가격 상승이 소매 가격에도 반영되기 시작했다.'),
('n1-1152','2026-12-02','赴任','ふにん','부임','任務・職務を命じられ、その勤務地へ行くこと。','来月から大阪支社へ赴任することになった。','다음 달부터 오사카 지사로 부임하게 되었다.'),
('n1-1167','2026-12-02','奨励','しょうれい','장려','望ましい活動・行為などを積極的にすすめ、励ますこと。','会社は資格取得を奨励し、受験費用の一部を補助している。','회사는 자격증 취득을 장려하고 응시 비용 일부를 지원하고 있다.'),
('n1-1171','2026-12-02','潜水','せんすい','잠수','水中にもぐること。','調査員は潜水して海底の設備を点検した。','조사원은 잠수해 해저 설비를 점검했다.'),
('n1-1175','2026-12-02','賠償','ばいしょう','배상','他人に与えた損害を、金銭などによって償うこと。','裁判所は会社に対して被害者への損害賠償を命じた。','법원은 회사에 피해자에 대한 손해배상을 명령했다.'),
('n1-1178','2026-12-02','意欲','いよく','의욕; 하고자 하는 적극적 마음','何かを進んで行おうとする積極的な気持ち。','本人に学ぶ意欲があれば、未経験でも大きく成長できる。','본인에게 배울 의욕이 있다면 미경험자라도 크게 성장할 수 있다.'),
('n1-1180','2026-12-02','命中','めいちゅう','명중','弾丸・矢などが狙った目標に当たること。','放たれた矢は的の中央に命中した。','쏜 화살은 과녁 중앙에 명중했다.'),
('n1-1186','2026-12-02','突破','とっぱ','돌파','障害・限界・防御などを打ち破って先へ進むこと。','応募者は書類選考を突破し、最終面接に進んだ。','지원자는 서류 심사를 통과해 최종 면접으로 진출했다.'),
('n1-1189','2026-12-02','抗争','こうそう','항쟁; 세력 간의 격렬한 다툼','対立する集団・勢力などが互いに争うこと。','長年続いた派閥間の抗争が組織の弱体化を招いた。','오랫동안 이어진 파벌 간 항쟁이 조직의 약화를 초래했다.'),
('n1-1192','2026-12-02','冒頭','ぼうとう','서두; 맨 처음','文章・発言・出来事などの最初の部分。','講演の冒頭で、講師は研究の目的を簡潔に説明した。','강연 서두에서 강사는 연구 목적을 간단히 설명했다.'),
('n1-1197','2026-12-02','全盛','ぜんせい','전성; 가장 번성한 상태','勢力・人気・能力などが最も盛んな状態。','その歌手は全盛期に数々の記録を打ち立てた。','그 가수는 전성기에 수많은 기록을 세웠다.'),
('n1-1199','2026-12-02','嫉妬','しっと','질투','他人の成功・能力・愛情などをうらやみ、ねたむ気持ち。','他人への嫉妬に振り回されるより、自分の目標に集中した方がよい。','타인에 대한 질투에 휘둘리기보다 자신의 목표에 집중하는 편이 좋다.'),
('n1-1200','2026-12-02','面目','めんぼく','면목; 체면; 명예','世間に対する体面・名誉。また、人や物事の本来の姿・価値。','重要な役割を果たせず、責任者として面目が立たない。','중요한 역할을 다하지 못해 책임자로서 면목이 서지 않는다.'),
('n1-1202','2026-12-02','市街','しがい','시가지; 도심의 건물이 밀집한 지역','建物・商店・道路などが集中している都市の区域。','駅を出ると、古い住宅地から近代的な市街へ景色が変わる。','역을 나오면 오래된 주택가에서 현대적인 시가지로 풍경이 바뀐다.'),
('n1-1208','2026-12-02','持続','じぞく','지속','ある状態・作用などが途切れずに続くこと。また、続けて保つこと。','一時的な効果ではなく、持続可能な改善策が求められている。','일시적인 효과가 아니라 지속 가능한 개선책이 요구되고 있다.'),
('n1-1214','2026-12-02','打撃','だげき','타격; 큰 손해; 타격 행위','物を強く打つこと。野球で球を打つこと。また比喩的に、大きな損害・精神的影響を受けること。','主要取引先の撤退は会社の業績に大きな打撃を与えた。','주요 거래처의 철수는 회사 실적에 큰 타격을 주었다.'),
('n1-1218','2026-12-02','改修','かいしゅう','개수; 보수; 수리 개선','建物・設備・システムなどの悪い部分を直し、機能・安全性などを改善すること。','老朽化した設備の改修には数か月かかる見込みだ。','노후 설비 개수에는 몇 달이 걸릴 전망이다.'),
('n1-1219','2026-12-02','云々','うんぬん','운운; 이러쿵저러쿵; 기타 등등','引用・説明などで、後の内容を省略して『など』の意を表す語。また、ある事柄についてあれこれ言うこと。','形式が古い云々という批判より、実際に使いにくい点を具体的に示してほしい。','형식이 낡았다느니 하는 비판보다 실제로 쓰기 불편한 점을 구체적으로 보여 주었으면 한다.'),
('n1-1223','2026-12-02','一筋','ひとすじ','한길; 오직 한 가지; 한 줄기','一本の細い線・道。また、一つのことだけに心を向けて続けること。','彼は三十年間、研究一筋でこの分野に取り組んできた。','그는 30년 동안 연구 한길만 걸으며 이 분야에 힘써 왔다.'),
('n1-1225','2026-12-02','子息','しそく','아드님; 아들','他人の息子を敬っていう語。','社長のご子息も同じ業界で働いているそうだ。','사장님의 아드님도 같은 업계에서 일하고 있다고 한다.'),
('n1-1232','2026-12-03','重複','じゅうふく','중복','同じ内容・事柄などが二重以上に重なること。','登録データに重複がないか、投入前にチェックする。','등록 데이터에 중복이 없는지 투입 전에 확인한다.'),
('n1-1233','2026-12-03','格差','かくさ','격차','所得・能力・待遇・地域などの間にある大きな差。','地域による教育環境の格差を縮める対策が求められている。','지역에 따른 교육 환경 격차를 줄이는 대책이 요구되고 있다.'),
('n1-1234','2026-12-03','短縮','たんしゅく','단축','時間・距離・期間などを短くすること。','処理を自動化したことで作業時間を大幅に短縮できた。','처리를 자동화해 작업 시간을 크게 단축할 수 있었다.'),
('n1-1236','2026-12-03','観衆','かんしゅう','관중; 관객','競技・公演などを見るために集まった大勢の人々。','試合終了の瞬間、観衆から大きな歓声が上がった。','경기가 끝나는 순간 관중에게서 큰 환호성이 터졌다.'),
('n1-1245','2026-12-03','沈黙','ちんもく','침묵','言葉を発さず黙っていること。また、意見や反応を示さないこと。','質問の後、会議室にはしばらく沈黙が続いた。','질문 뒤 회의실에는 한동안 침묵이 이어졌다.'),
('n1-1247','2026-12-03','手錠','てじょう','수갑','人の両手首を拘束して自由に動けなくするための器具。','警察官は容疑者を確保し、手錠をかけた。','경찰관은 용의자를 확보해 수갑을 채웠다.'),
('n1-1250','2026-12-03','皇居','こうきょ','황거; 일본 천황의 거처','天皇が住み、公的な儀式なども行われる宮殿・居所。','皇居周辺は観光客やランナーにもよく知られている。','황거 주변은 관광객과 러너들에게도 잘 알려져 있다.'),
('n1-1257','2026-12-03','待遇','たいぐう','대우; 처우; 근로 조건','人をどのように扱うかという条件・方式。特に給与・地位・福利厚生などの勤務条件。','人材確保のため、給与だけでなく待遇全体を見直した。','인재 확보를 위해 급여뿐 아니라 처우 전반을 재검토했다.'),
('n1-1265','2026-12-03','共存','きょうそん','공존','異なるものが互いを排除せず、同時に存在すること。','自然環境と都市機能が共存できる計画が求められている。','자연환경과 도시 기능이 공존할 수 있는 계획이 요구되고 있다.'),
('n1-1266','2026-12-03','前途','ぜんと','전도; 앞날; 장래','これから先の道のり・将来。特に将来の見込みや可能性。','新しい事業の前途は決して平坦ではないが、成長の余地は大きい。','새 사업의 앞날이 결코 순탄하지는 않지만 성장 여지는 크다.'),
('n1-1270','2026-12-03','延べ','のべ','연인원·연시간 등 중복 포함 합계','同じ人・物・時間などの重複を含めて、回数ごとに数えた合計。','イベントには三日間で延べ一万人が来場した。','행사에는 사흘 동안 연인원 1만 명이 방문했다.'),
('n1-1277','2026-12-03','忠告','ちゅうこく','충고; 조언','相手のためを思い、過ち・危険・改善点などを真剣に注意して教えること。','先輩の忠告を受け入れ、計画をもう一度見直した。','선배의 충고를 받아들여 계획을 다시 검토했다.'),
('n1-1278','2026-12-03','群集','ぐんしゅう','군집; 집단','多くの人・生物・物などが一か所に集まること。また、その集まり。','駅前にはイベント開始を待つ群集ができていた。','역 앞에는 행사 시작을 기다리는 군중이 모여 있었다.'),
('n1-1284','2026-12-03','恥','はじ','수치; 부끄러움','自分の欠点・失敗・不名誉な行為などによって感じる強い羞恥。','失敗そのものを恥と考えるより、そこから学ぶ姿勢が大切だ。','실패 자체를 수치로 여기기보다 거기서 배우는 자세가 중요하다.'),
('n1-1288','2026-12-03','消去','しょうきょ','삭제; 소거','文字・記録・データ・痕跡などを消してなくすこと。','誤って重要なデータを消去しないよう確認画面を設けた。','실수로 중요한 데이터를 삭제하지 않도록 확인 화면을 마련했다.'),
('n1-1289','2026-12-03','沿岸','えんがん','연안; 해안가','海・湖・川などの岸に沿った地域。','台風の接近に伴い、沿岸地域では高波への警戒が続いている。','태풍 접근에 따라 연안 지역에서는 높은 파도에 대한 경계가 이어지고 있다.'),
('n1-1290','2026-12-03','休戦','きゅうせん','휴전','交戦している双方が合意などによって戦闘を一時中止すること。','双方は人道支援のため一時休戦に合意した。','양측은 인도적 지원을 위해 일시 휴전에 합의했다.'),
('n1-1293','2026-12-03','一心','いっしん','일심; 한마음; 오직 한 가지에 집중함','一つのことだけに心を集中すること。また、心を一つにすること。','彼は目標達成だけを考え、一心に練習を続けた。','그는 목표 달성만 생각하며 한마음으로 연습을 계속했다.'),
('n1-1299','2026-12-03','繁殖','はんしょく','번식','生物が子孫を増やし、個体数を増加させること。','外来種が急速に繁殖し、生態系への影響が懸念されている。','외래종이 빠르게 번식해 생태계에 미칠 영향이 우려되고 있다.'),
('n1-1301','2026-12-03','納入','のうにゅう','납입; 납품','金銭を納めること。また、注文された品物を指定先へ納めること。','機器は今月末までに顧客へ納入する予定だ。','기기는 이달 말까지 고객에게 납품할 예정이다.');
INSERT INTO _n1_b5_words_0106(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1304','2026-12-04','下位','かい','하위; 낮은 순위','順位・位置・等級などが低いこと。また、その位置。','下位のチームでも終盤に大きく順位を上げる可能性はある。','하위 팀이라도 막판에 순위를 크게 올릴 가능성은 있다.'),
('n1-1307','2026-12-04','承諾','しょうだく','승낙; 동의','相手からの依頼・提案・申し出などを受け入れること。','本人の承諾を得ずに写真を公開してはいけない。','본인의 승낙 없이 사진을 공개해서는 안 된다.'),
('n1-1312','2026-12-04','疑惑','ぎわく','의혹','事実ではないかと疑われること。また、その疑い。','会計処理をめぐる疑惑について第三者委員会が調査を始めた。','회계 처리를 둘러싼 의혹에 대해 제3자 위원회가 조사를 시작했다.'),
('n1-1314','2026-12-04','破棄','はき','파기; 폐기','契約・約束・文書などを無効にする。また、不要なものを捨てること。','機密資料は規定に従って安全に破棄しなければならない。','기밀 자료는 규정에 따라 안전하게 폐기해야 한다.'),
('n1-1317','2026-12-04','真相','しんそう','진상; 실제 사실','事件・問題などの偽りのない本当の事情・姿。','事故の真相を明らかにするため、関係者への聞き取りが続いている。','사고의 진상을 밝히기 위해 관계자 면담이 계속되고 있다.'),
('n1-1320','2026-12-04','便宜','べんぎ','편의; 편리하도록 해 주는 조치','都合がよく便利であること。また、物事がしやすいよう取り計らうこと。','利用者の便宜を図り、窓口の受付時間を延長した。','이용자의 편의를 도모해 창구 접수 시간을 연장했다.'),
('n1-1331','2026-12-04','黒字','くろじ','흑자','収入・売上などが支出・費用を上回り、利益が出ている状態。','新規事業は三年目にして初めて黒字に転じた。','신규 사업은 3년째에 처음으로 흑자로 전환했다.'),
('n1-1335','2026-12-04','侮辱','ぶじょく','모욕; 업신여김','相手を見下し、言葉や態度によって名誉・尊厳を傷つけること。','相手の出身を理由に侮辱する発言は許されない。','상대의 출신을 이유로 모욕하는 발언은 용납될 수 없다.'),
('n1-1337','2026-12-04','結束','けっそく','결속; 단결','同じ目的を持つ人々が心や力を一つにまとめること。','困難な状況を乗り越えるには、チームの結束が欠かせない。','어려운 상황을 극복하려면 팀의 결속이 필수다.'),
('n1-1340','2026-12-04','諸君','しょくん','제군; 여러분','話し手が同輩または目下の複数の人に、一定の敬意を込めて呼びかける語。','指導者は若者たちに向かって『諸君の挑戦に期待する』と語った。','지도자는 젊은이들을 향해 ''여러분의 도전을 기대한다''고 말했다.'),
('n1-1346','2026-12-04','落ち着き','おちつき','침착함; 차분함','感情や態度が安定していて、慌てず静かであること。','障害発生時ほど、担当者には落ち着きのある対応が求められる。','장애 발생 시일수록 담당자에게는 침착한 대응이 요구된다.'),
('n1-1348','2026-12-04','強行','きょうこう','강행; 무리하게 실행함','反対・困難・危険などがあっても、予定や方針を押し切って実行すること。','悪天候の中でイベントを強行した判断には批判が集まった。','악천후 속에서 행사를 강행한 판단에 비판이 쏟아졌다.'),
('n1-1350','2026-12-04','軍艦','ぐんかん','군함','海軍に所属し、戦闘・警戒などの軍事目的で用いられる船。','港には歴史資料として保存された旧軍艦が展示されている。','항구에는 역사 자료로 보존된 옛 군함이 전시되어 있다.'),
('n1-1352','2026-12-04','診療','しんりょう','진료','医師が患者を診察し、必要な治療を行うこと。','この診療所では休日も午前中に診療を行っている。','이 진료소에서는 휴일에도 오전 중 진료를 한다.'),
('n1-1354','2026-12-04','軽蔑','けいべつ','경멸; 업신여김','相手を価値の低いものと見て、見下し尊重しないこと。','職業を理由に人を軽蔑するような態度は許されない。','직업을 이유로 사람을 경멸하는 태도는 용납될 수 없다.'),
('n1-1358','2026-12-04','指図','さしず','지시; 명령','人に何をどのようにするか具体的に命じたり指示したりすること。','現場を知らない人が細かく指図すると、かえって作業が混乱する。','현장을 모르는 사람이 세세하게 지시하면 오히려 작업이 혼란스러워진다.'),
('n1-1360','2026-12-04','着目','ちゃくもく','주목; 착안','重要・特徴的だと思う点に特に注意を向けること。','研究チームは利用者の行動変化に着目して分析を進めた。','연구팀은 이용자의 행동 변화에 주목해 분석을 진행했다.'),
('n1-1363','2026-12-04','万人','ばんじん','만인; 모든 사람','すべての人。非常に多くの人を一般化していう語。','万人にとって使いやすい制度を作るのは容易ではない。','모든 사람에게 사용하기 쉬운 제도를 만드는 것은 쉽지 않다.'),
('n1-1371','2026-12-04','弁解','べんかい','변명; 해명','自分の失敗・過失などについて事情を説明し、非難を軽くしようとすること。','ミスの原因を説明することは必要だが、弁解ばかりでは信頼を失う。','실수 원인을 설명하는 것은 필요하지만 변명만 하면 신뢰를 잃는다.'),
('n1-1377','2026-12-04','陳列','ちんれつ','진열','商品・作品などを人に見せるため、見やすく並べて置くこと。','新商品は入口近くの棚に陳列されている。','신상품은 입구 근처 선반에 진열되어 있다.'),
('n1-1387','2026-12-05','傍ら','かたわら','곁; 한편으로는; ~하는 한편','すぐそば。また、主な仕事・活動をする一方で別のことも行うことを表す。','彼は会社員として働く傍ら、週末には地域の子どもたちに数学を教えている。','그는 회사원으로 일하는 한편 주말에는 지역 아이들에게 수학을 가르친다.'),
('n1-1396','2026-12-05','偏見','へんけん','편견','十分な根拠がないまま、特定の人・集団・物事について偏った見方をすること。','年齢だけで能力を判断するのは偏見につながりかねない。','나이만으로 능력을 판단하는 것은 편견으로 이어질 수 있다.'),
('n1-1400','2026-12-05','海峡','かいきょう','해협','二つの陸地に挟まれ、二つの海域を結ぶ細長い海の部分。','この海峡は国際的な海上交通の重要なルートになっている。','이 해협은 국제 해상 교통의 중요한 항로가 되고 있다.'),
('n1-1408','2026-12-05','恵み','めぐみ','은혜; 혜택; 자연이 주는 혜택','自然・神・人などから与えられる、生活を豊かにする恩恵や利益。','豊かな水の恵みによって、この地域では農業が発展してきた。','풍부한 물의 혜택 덕분에 이 지역에서는 농업이 발전해 왔다.'),
('n1-1412','2026-12-05','内陸','ないりく','내륙','海岸から離れた陸地の内部。','内陸部では昼夜の気温差が大きくなることがある。','내륙 지역에서는 낮과 밤의 기온 차가 커질 수 있다.'),
('n1-1419','2026-12-05','控除','こうじょ','공제; 일정 금액을 빼는 것','合計額から一定の金額・数量を差し引くこと。税・給与・保険などでよく用いる。','給与から社会保険料などが控除された後の金額が振り込まれる。','급여에서 사회보험료 등이 공제된 뒤의 금액이 입금된다.'),
('n1-1425','2026-12-05','下地','したじ','밑바탕; 기초; 소질','物を仕上げる前の基礎となる面・材料。また比喩的に、能力・知識・状況などの基礎。','大学で学んだ統計の知識が、現在の分析業務の下地になっている。','대학에서 배운 통계 지식이 현재 분석 업무의 밑바탕이 되고 있다.'),
('n1-1428','2026-12-05','手分け','てわけ','분담; 일을 나누어 맡음','複数の人が仕事・範囲などを分け、それぞれ担当して進めること。','時間がないので、資料確認と会場準備を手分けして進めよう。','시간이 없으니 자료 확인과 행사장 준비를 나누어 진행하자.'),
('n1-1429','2026-12-05','ニュアンス','ニュアンス','뉘앙스; 미묘한 어감·느낌','言葉・表現・色・音などが持つ、はっきり言い切れない微妙な意味・感じの違い。','同じ意味の単語でも、文脈によってニュアンスが少し異なる。','같은 의미의 단어라도 문맥에 따라 뉘앙스가 조금 다르다.'),
('n1-1430','2026-12-05','捕虜','ほりょ','포로; 전쟁 포로','戦争・戦闘で敵側に捕らえられ、拘束された兵士など。','条約では捕虜の人道的な取り扱いについて定めている。','조약에서는 포로의 인도적인 처우에 대해 정하고 있다.'),
('n1-1432','2026-12-05','雑貨','ざっか','잡화; 생활 소품','文房具・台所用品・装飾品など、日常生活で使うさまざまな小物・商品。','駅前に食品と雑貨を扱う小さな店が開店した。','역 앞에 식품과 잡화를 취급하는 작은 가게가 문을 열었다.'),
('n1-1436','2026-12-05','奮闘','ふんとう','분투; 힘껏 노력함','困難な状況や強い相手に対し、力いっぱい努力して立ち向かうこと。','少人数のチームが短い納期に間に合わせるため奮闘した。','소수 인원의 팀이 짧은 납기를 맞추기 위해 분투했다.'),
('n1-1451','2026-12-05','中和','ちゅうわ','중화','性質の異なるものを作用させ、互いの強い性質を弱めたり中間的な状態にしたりすること。化学では酸と塩基の反応などをいう。','酸性の排水は処理設備で中和してから放流される。','산성 폐수는 처리 설비에서 중화한 뒤 방류된다.'),
('n1-1452','2026-12-05','墜落','ついらく','추락','航空機・物体・人などが高い所から急激に落ちること。','事故調査委員会は航空機が墜落した原因を調べている。','사고조사위원회는 항공기가 추락한 원인을 조사하고 있다.'),
('n1-1462','2026-12-05','操縦','そうじゅう','조종; 운전','航空機・船・大型機械などを操作して、思いどおりに動かすこと。','悪天候の中で機体を安全に操縦するには高度な技術が必要だ。','악천후 속에서 기체를 안전하게 조종하려면 고도의 기술이 필요하다.'),
('n1-1463','2026-12-05','禁物','きんもつ','금물; 해서는 안 되는 것','ある状況で避けるべきこと、してはいけないこと。','体調が悪い時に無理をするのは禁物だ。','몸 상태가 좋지 않을 때 무리하는 것은 금물이다.'),
('n1-1468','2026-12-05','誘惑','ゆうわく','유혹; 꾐','魅力的な言葉・利益・欲望などによって、相手の心を引きつけ行動を促すこと。','短期的な利益の誘惑に負けず、長期的な安全性を優先すべきだ。','단기 이익의 유혹에 넘어가지 말고 장기적인 안전성을 우선해야 한다.'),
('n1-1469','2026-12-05','暴露','ばくろ','폭로; 숨겨진 사실을 드러냄','秘密・不正・隠されていた事実などを明るみに出して公に知らせること。','内部資料の暴露をきっかけに、不正会計の疑惑が広がった。','내부 자료 폭로를 계기로 분식회계 의혹이 확산됐다.'),
('n1-1479','2026-12-05','普遍','ふへん','보편; 널리 공통됨','特定の時代・場所・人に限らず、広く共通して成り立つこと。','安全を重視する姿勢は、業界を問わず普遍的な価値だ。','안전을 중시하는 자세는 업계를 불문하고 보편적인 가치다.'),
('n1-1485','2026-12-05','行き違い','いきちがい','엇갈림; 오해; 의사소통 착오','互いに別の方向へ進んですれ違うこと。また、連絡・理解・意図などがうまくかみ合わず誤解が生じること。','担当者同士の認識の行き違いから、同じ作業を二重に進めてしまった。','담당자끼리 인식이 엇갈려 같은 작업을 이중으로 진행해 버렸다.');
INSERT INTO _n1_b5_words_0106(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1488','2026-12-06','均衡','きんこう','균형; 평형','複数の力・要素・利益などが一方に偏らず、釣り合っている状態。','都市開発では経済性と環境保護の均衡を取る必要がある。','도시 개발에서는 경제성과 환경 보호의 균형을 맞출 필요가 있다.'),
('n1-1489','2026-12-06','逃走','とうそう','도주; 달아남','追跡・逮捕などを避けるため、その場から逃げ去ること。','容疑者は現場から車で逃走したが、その日のうちに逮捕された。','용의자는 현장에서 차로 도주했지만 그날 안에 체포됐다.'),
('n1-1496','2026-12-06','悲鳴','ひめい','비명; 비유적으로 감당하기 힘든 호소','恐怖・苦痛・驚きなどによって思わず上げる鋭い声。また比喩的に、非常に苦しい状態を訴える声。','急な物価上昇に、多くの事業者が悲鳴を上げている。','급격한 물가 상승에 많은 사업자가 비명을 지르고 있다.'),
('n1-1503','2026-12-06','養護','ようご','양호; 보호·돌봄','健康や生活を守り、必要な保護・世話を行うこと。','体調が悪くなった生徒は養護教諭のいる保健室で休んだ。','몸 상태가 나빠진 학생은 보건교사가 있는 보건실에서 쉬었다.'),
('n1-1506','2026-12-06','土手','どて','둑; 제방','川・池などの水があふれるのを防ぐため、土を盛って築いた堤。','春になると川沿いの土手に多くの花が咲く。','봄이 되면 강변 둑에 많은 꽃이 핀다.'),
('n1-1510','2026-12-06','燃焼','ねんしょう','연소','物質が酸素などと反応して熱・光を出しながら燃えること。','燃料を完全に燃焼させることで、有害物質の発生を抑える。','연료를 완전히 연소시켜 유해 물질 발생을 억제한다.'),
('n1-1511','2026-12-06','愚痴','ぐち','푸념; 불평','自分の不満・つらさなどを、解決を求めずくどくどと言うこと。また、その言葉。','愚痴をこぼすだけでは状況は変わらないので、改善策を考えることにした。','푸념만 해서는 상황이 바뀌지 않으므로 개선책을 생각하기로 했다.'),
('n1-1515','2026-12-06','建前','たてまえ','겉으로 내세우는 원칙; 명분','表向きに示す方針・原則・理由。本心と対比して用いられることが多い。','制度上の建前と現場の実情が大きく食い違っている。','제도상의 명분과 현장의 실정이 크게 어긋나 있다.'),
('n1-1518','2026-12-06','金槌','かなづち','쇠망치; 수영을 못하는 사람','鉄製の槌。また比喩的に、まったく泳げない人。','私は金槌なので、海では必ず救命胴衣を着る。','나는 수영을 전혀 못해서 바다에서는 반드시 구명조끼를 입는다.'),
('n1-1521','2026-12-06','寒気','かんき','한기; 찬 공기','冷たい空気。また、周囲に感じられる冷えた気配。','窓を開けると強い寒気が室内に流れ込んできた。','창문을 여니 강한 찬 공기가 실내로 들어왔다.'),
('n1-1522','2026-12-06','ゆとり','ゆとり','여유; 여력','時間・金銭・空間・気持ちなどに余裕があり、差し迫っていない状態。','納期に少しゆとりを持たせて、確認作業の時間を確保した。','납기에 조금 여유를 두어 확인 작업 시간을 확보했다.'),
('n1-1523','2026-12-06','軍備','ぐんび','군비; 군사 장비와 준비','戦争・防衛に備えて整える兵器・施設・兵力などの軍事的な装備。','政府は周辺情勢を踏まえ、軍備のあり方を見直している。','정부는 주변 정세를 고려해 군비의 방향을 재검토하고 있다.'),
('n1-1525','2026-12-06','逆立ち','さかだち','물구나무서기','両手などを地面につき、足を上にして体を逆さに立てること。','子どもたちは体育の授業で壁を使って逆立ちを練習した。','아이들은 체육 시간에 벽을 이용해 물구나무서기를 연습했다.'),
('n1-1528','2026-12-06','兆し','きざし','조짐; 징조; 기미','ある出来事・変化が起こりそうだと感じさせる気配。','長く低迷していた市場にも回復の兆しが見え始めた。','오랫동안 침체했던 시장에도 회복 조짐이 보이기 시작했다.'),
('n1-1529','2026-12-06','購買','こうばい','구매; 구입','商品・物品などを金銭を支払って買うこと。','原材料の購買を一元化し、調達コストを削減した。','원자재 구매를 일원화해 조달 비용을 줄였다.'),
('n1-1530','2026-12-06','氾濫','はんらん','범람; 넘쳐남','川などの水が増えて堤防を越え、周囲にあふれ出ること。また比喩的に、物事が過度に出回ること。','豪雨で川が氾濫し、周辺の道路が冠水した。','폭우로 강이 범람해 주변 도로가 침수되었다.'),
('n1-1531','2026-12-06','修士','しゅうし','석사; 석사 학위','大学院の修士課程などを修了した者に授与される学位。','彼女は大学院で情報工学を学び、修士の学位を取得した。','그녀는 대학원에서 정보공학을 공부해 석사 학위를 취득했다.'),
('n1-1535','2026-12-06','感度','かんど','감도; 민감도','光・音・電波などの刺激を機器や感覚がどの程度敏感に受け取るかを表す度合い。','暗い場所で撮影するため、カメラの感度を上げた。','어두운 곳에서 촬영하기 위해 카메라 감도를 높였다.'),
('n1-1536','2026-12-06','驚異','きょうい','경이; 놀라운 것','常識では考えにくいほど非常に優れ、驚かされること。また、そのような事物。','この十年間の技術進歩はまさに驚異と言える。','지난 10년간의 기술 발전은 정말 경이라고 할 수 있다.'),
('n1-1538','2026-12-06','雑談','ざつだん','잡담; 가벼운 대화','特に決まった目的・テーマを設けず、気軽に話すこと。','会議の前に少し雑談をしたことで、場の緊張が和らいだ。','회의 전에 잠깐 잡담을 해서 분위기의 긴장이 풀렸다.'),
('n1-1539','2026-12-07','沈没','ちんぼつ','침몰; 가라앉음','船などが水中に沈んで姿を消すこと。','事故で損傷した船は港へ戻る途中で沈没した。','사고로 파손된 배는 항구로 돌아오던 중 침몰했다.'),
('n1-1542','2026-12-07','発病','はつびょう','발병','それまで健康だった人に病気の症状が現れ、病気になること。','発病の時期を特定するため、過去の診療記録を確認した。','발병 시기를 특정하기 위해 과거 진료 기록을 확인했다.'),
('n1-1554','2026-12-07','浴室','よくしつ','욕실','浴槽・シャワーなどがあり、入浴するための部屋。','浴室の換気を怠ると、カビが発生しやすくなる。','욕실 환기를 소홀히 하면 곰팡이가 생기기 쉬워진다.'),
('n1-1555','2026-12-07','同封','どうふう','동봉','封筒・荷物などに、別の書類・品物を一緒に入れること。','必要事項を記入し、返信用封筒を同封して返送してください。','필요 사항을 기입하고 회신용 봉투를 동봉해 반송해 주세요.'),
('n1-1560','2026-12-07','尻尾','しっぽ','꼬리','動物の胴体の後部から細長く伸びた部分。また比喩的に、物の後端をいう。','犬は飼い主を見つけると嬉しそうに尻尾を振った。','개는 주인을 발견하자 기쁜 듯 꼬리를 흔들었다.'),
('n1-1564','2026-12-07','断面','だんめん','단면; 절단면','物を切ったときに現れる面。また比喩的に、物事の一つの側面。','材料の断面を顕微鏡で観察し、内部構造を調べた。','재료의 단면을 현미경으로 관찰해 내부 구조를 조사했다.'),
('n1-1567','2026-12-07','肉親','にくしん','육친; 혈육','親子・兄弟姉妹など、血のつながりが非常に近い家族。','災害後、離れ離れになった肉親を捜す人が相次いだ。','재해 후 헤어진 혈육을 찾는 사람들이 잇따랐다.'),
('n1-1568','2026-12-07','近視','きんし','근시','近くは見えるが、遠くの物がはっきり見えにくい視力の状態。','近視が進み、遠くの標識が見えにくくなった。','근시가 심해져 먼 표지판이 잘 보이지 않게 되었다.'),
('n1-1569','2026-12-07','名札','なふだ','명찰; 이름표','氏名・所属などを書いて、衣服・机・場所などに付ける札。','受付で名札を受け取り、胸につけて会場に入った。','접수처에서 명찰을 받아 가슴에 달고 행사장에 들어갔다.'),
('n1-1570','2026-12-07','封鎖','ふうさ','봉쇄; 차단','出入り・通行・交通などができないように閉じて遮断すること。','事故の影響で道路の一部が一時封鎖された。','사고 영향으로 도로 일부가 일시 봉쇄되었다.'),
('n1-1571','2026-12-07','修了','しゅうりょう','수료','学校・研修などで定められた課程をすべて終えること。','半年間の研修を修了した社員に証明書が授与された。','6개월간의 연수를 수료한 사원들에게 증명서가 수여되었다.'),
('n1-1575','2026-12-07','区切り','くぎり','구분; 매듭; 한 단락','連続する物事を分ける境目。また、仕事・期間などのひとまとまりが終わる節目。','この作業に区切りがついたら、次の工程へ進もう。','이 작업이 한 단락 마무리되면 다음 공정으로 넘어가자.'),
('n1-1579','2026-12-07','血管','けっかん','혈관','体内で血液を運ぶ管。動脈・静脈・毛細血管などがある。','運動には血管の健康を保つ効果も期待されている。','운동에는 혈관 건강을 유지하는 효과도 기대되고 있다.'),
('n1-1581','2026-12-07','脚色','きゃくしょく','각색; 윤색','小説・事実などを舞台・映画向けに作り変えること。また、事実に手を加えて話を面白く見せること。','実話をもとにした作品だが、物語には一部脚色が加えられている。','실화를 바탕으로 한 작품이지만 이야기에는 일부 각색이 더해져 있다.'),
('n1-1582','2026-12-07','刺繍','ししゅう','자수','布に色糸などを縫い込んで、模様・文字・絵を表すこと。また、その作品。','祖母は布に花の模様を刺繍して小さな袋を作った。','할머니는 천에 꽃무늬를 자수해 작은 주머니를 만들었다.'),
('n1-1584','2026-12-07','固体','こたい','고체','一定の形と体積を保つ物質の状態。液体・気体と対になる。','水は温度によって固体・液体・気体の状態に変化する。','물은 온도에 따라 고체·액체·기체 상태로 변한다.'),
('n1-1586','2026-12-07','お手上げ','おてあげ','속수무책; 두 손 듦','どうしてよいか分からず、もはや自分では対処できない状態。','原因が全く再現できず、現場だけではお手上げの状態だった。','원인이 전혀 재현되지 않아 현장만으로는 속수무책인 상태였다.'),
('n1-1587','2026-12-07','火花','ひばな','불꽃; 불티','燃えている物や金属の衝突などから飛び散る小さな光。また比喩的に、激しい対立を表す。','金属を切断すると、工具の先から火花が飛び散った。','금속을 절단하자 공구 끝에서 불꽃이 튀었다.'),
('n1-1588','2026-12-07','噴出','ふんしゅつ','분출; 솟구쳐 나옴','液体・気体などが強い勢いで外へ噴き出すこと。','配管が破損し、内部の蒸気が一気に噴出した。','배관이 파손되어 내부 증기가 한꺼번에 분출했다.'),
('n1-1589','2026-12-07','捕獲','ほかく','포획; 붙잡음','逃げる動物・人物などを捕らえること。','市は住宅地に現れた野生動物の捕獲を専門業者に依頼した。','시는 주택가에 나타난 야생동물 포획을 전문 업체에 의뢰했다.');
INSERT INTO _n1_b5_words_0106(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1590','2026-12-08','私用','しよう','사적인 용무; 개인 용도','仕事・公務ではない、個人的な用事や用途。','社用車を私用で使うことは禁止されている。','회사 차량을 사적인 용도로 사용하는 것은 금지되어 있다.'),
('n1-1591','2026-12-08','寄贈','きそう','기증; 증정','学校・図書館・団体などに、物品を無償で贈ること。','卒業生から大学図書館へ貴重な資料が寄贈された。','졸업생이 대학 도서관에 귀중한 자료를 기증했다.'),
('n1-1592','2026-12-08','新婚','しんこん','신혼','結婚して間もないこと。また、その時期。','二人は新婚生活を始めるため、新しい部屋を借りた。','두 사람은 신혼생활을 시작하기 위해 새 집을 빌렸다.'),
('n1-1593','2026-12-08','出題','しゅつだい','출제','試験・クイズなどで問題を作って提示すること。','今年の試験では実務に近い判断問題が多く出題された。','올해 시험에서는 실무에 가까운 판단 문제가 많이 출제되었다.'),
('n1-1595','2026-12-08','趣','おもむき','정취; 운치; 특유의 느낌','物・場所・作品などから感じられる独特の味わい・雰囲気。','古い町並みには現代の都市にはない趣がある。','오래된 거리에는 현대 도시에는 없는 정취가 있다.'),
('n1-1600','2026-12-08','鉛','なまり','납','重くて柔らかい灰色の金属元素。電池・遮蔽材などに使われる。','古い塗料には鉛が含まれている場合があるため注意が必要だ。','오래된 페인트에는 납이 포함된 경우가 있어 주의가 필요하다.'),
('n1-1602','2026-12-08','爆破','ばくは','폭파','爆発物などを使って建物・設備・岩盤などを破壊すること。','老朽化した建物は周辺の安全を確保したうえで爆破された。','노후화한 건물은 주변 안전을 확보한 뒤 폭파되었다.'),
('n1-1608','2026-12-08','勧誘','かんゆう','권유; 가입 권유; 모집','人に参加・加入・購入などをするようすすめること。','駅前で投資商品の勧誘を受けたが、その場では契約しなかった。','역 앞에서 투자 상품 가입 권유를 받았지만 그 자리에서는 계약하지 않았다.'),
('n1-1609','2026-12-08','街頭','がいとう','가두; 길거리','町の道路上や、人通りの多い通り。','候補者は駅前で街頭演説を行った。','후보자는 역 앞에서 가두연설을 했다.'),
('n1-1610','2026-12-08','尿','にょう','소변; 오줌','腎臓で作られ、体内の老廃物とともに排出される液体。','健康診断では血液だけでなく尿の検査も行われた。','건강검진에서는 혈액뿐 아니라 소변 검사도 실시되었다.'),
('n1-1612','2026-12-08','憎しみ','にくしみ','미움; 증오','人・物事を強く憎む感情。','憎しみをぶつけ合っても問題の解決にはつながらない。','서로 증오를 쏟아내도 문제 해결로 이어지지 않는다.'),
('n1-1616','2026-12-08','磁器','じき','자기; 도자기류','陶石などを高温で焼いて作る、白く硬く吸水性の低い焼き物。','この地方は白い磁器の生産地として古くから知られている。','이 지방은 흰 자기 생산지로 예전부터 알려져 있다.'),
('n1-1623','2026-12-08','庶務','しょむ','서무; 일반 행정 업무','組織で、文書・備品・連絡・施設管理など幅広い日常事務を扱う仕事。','備品の発注や郵便物の管理は庶務担当が行っている。','비품 발주와 우편물 관리는 서무 담당이 하고 있다.'),
('n1-1626','2026-12-08','眼科','がんか','안과','目の病気・視力などを診察・治療する医学分野。また、その診療科。','視界が急にぼやけたため、念のため眼科を受診した。','시야가 갑자기 흐려져 만일을 위해 안과 진료를 받았다.'),
('n1-1627','2026-12-08','繁盛','はんじょう','번창; 성업','商売・店などに客が多く集まり、非常に栄えること。','駅前に移転してから店は以前より繁盛するようになった。','역 앞으로 이전한 뒤 가게는 이전보다 더 번창하게 되었다.'),
('n1-1631','2026-12-08','異性','いせい','이성; 다른 성별','自分とは異なる性別の人。','異性との交友関係だけを特別視する必要はない。','이성과의 교우 관계만 특별하게 볼 필요는 없다.'),
('n1-1632','2026-12-08','行員','こういん','은행원','銀行に勤務する職員。','窓口の行員が口座開設の手続きを丁寧に説明してくれた。','창구 은행원이 계좌 개설 절차를 친절하게 설명해 주었다.'),
('n1-1636','2026-12-08','必修','ひっしゅう','필수 이수','学校などで、必ず履修・修得しなければならないこと。','この科目は一年生全員の必修となっている。','이 과목은 1학년 전원의 필수 과목으로 지정되어 있다.'),
('n1-1637','2026-12-08','所々','しょしょ','여기저기; 곳곳','複数の場所。あちらこちら。','古い資料なので、所々に文字が読みにくい部分がある。','오래된 자료라 곳곳에 글자가 읽기 어려운 부분이 있다.'),
('n1-1638','2026-12-08','降水','こうすい','강수; 비나 눈이 내림','雨・雪・みぞれなどが大気中から地上へ落ちること。','この地域では夏に降水量が大きく増える。','이 지역에서는 여름에 강수량이 크게 늘어난다.'),
('n1-1639','2026-12-09','怪獣','かいじゅう','괴수','空想上の、巨大で恐ろしい姿をした動物・生物。','その映画では巨大な怪獣が都市に現れる。','그 영화에서는 거대한 괴수가 도시에 나타난다.'),
('n1-1640','2026-12-09','凶作','きょうさく','흉작','天候不順・災害などで農作物の収穫量が平年より著しく少ないこと。','長い干ばつの影響で今年は深刻な凶作となった。','긴 가뭄의 영향으로 올해는 심각한 흉작이 되었다.'),
('n1-1641','2026-12-09','出費','しゅっぴ','지출; 비용이 나감','金銭を支払って使うこと。また、その金額。','引っ越しの時期は家具や手続きで何かと出費がかさむ。','이사 시기에는 가구와 각종 절차 때문에 이런저런 지출이 늘어난다.'),
('n1-1643','2026-12-09','前売り','まえうり','예매; 선판매','公演・映画・乗車券などを利用日より前に販売すること。','人気公演なので、当日券ではなく前売り券を購入した。','인기 공연이라 당일권이 아니라 예매권을 구입했다.'),
('n1-1658','2026-12-09','奇数','きすう','홀수','二で割り切れない整数。','座席番号が奇数の人はこちらの列に並んでください。','좌석 번호가 홀수인 사람은 이 줄에 서 주세요.'),
('n1-1661','2026-12-09','防火','ぼうか','방화(防火); 화재 예방','火災の発生・延焼を防ぐこと。','倉庫では防火設備の点検を定期的に実施している。','창고에서는 화재 예방 설비 점검을 정기적으로 실시하고 있다.'),
('n1-1663','2026-12-09','光沢','こうたく','광택; 윤기','物の表面が光を反射してつややかに見えること。また、その輝き。','表面を磨くと金属本来の光沢が戻った。','표면을 닦자 금속 본래의 광택이 돌아왔다.'),
('n1-1665','2026-12-09','口述','こうじゅつ','구술; 말로 진술함','文章に書かず、口頭で述べること。','証人の口述内容はその場で記録された。','증인의 구술 내용은 그 자리에서 기록되었다.'),
('n1-1667','2026-12-09','発育','はついく','발육; 성장','生物の体が成長し、機能が発達すること。','十分な睡眠は子どもの健全な発育に欠かせない。','충분한 수면은 아이의 건강한 발육에 필수적이다.'),
('n1-1674','2026-12-09','模範','もはん','모범; 본보기','見習うべき優れた例・行動・人物。','彼の丁寧な顧客対応は新人の模範になっている。','그의 정중한 고객 대응은 신입의 모범이 되고 있다.'),
('n1-1678','2026-12-09','書き取り','かきとり','받아쓰기; 듣고 적기','読み上げられた語句・文章を聞いて、正しく書き写す練習。','授業の最後に漢字の書き取りを十問行った。','수업 마지막에 한자 받아쓰기를 10문제 했다.'),
('n1-1679','2026-12-09','舗装','ほそう','포장; 도로 포장','道路などの表面をアスファルト・コンクリートなどで固く平らに整えること。','道路の舗装工事のため、夜間は一部区間が通行止めになる。','도로 포장 공사 때문에 야간에는 일부 구간이 통행 금지된다.'),
('n1-1680','2026-12-09','差額','さがく','차액','二つの金額の差。','料金変更による差額は来月の請求で調整される。','요금 변경에 따른 차액은 다음 달 청구에서 조정된다.'),
('n1-1683','2026-12-09','愛憎','あいぞう','애증; 사랑과 미움','愛する気持ちと憎む気持ち。','長い関係の中で愛憎が入り混じった複雑な感情が生まれた。','오랜 관계 속에서 애증이 뒤섞인 복잡한 감정이 생겼다.'),
('n1-1684','2026-12-09','待望','たいぼう','대망; 오래 기다림','長い間、実現・登場などを強く待ち望むこと。','待望の新機能がついに次回の更新で追加される。','오랫동안 기다려 온 신기능이 드디어 다음 업데이트에서 추가된다.'),
('n1-1685','2026-12-09','下火','したび','기세가 꺾임; 쇠퇴세','盛んだった勢い・流行・活動などが弱まること。','一時的に過熱したブームも、最近ではすっかり下火になった。','한때 과열됐던 붐도 최근에는 완전히 기세가 꺾였다.'),
('n1-1686','2026-12-09','目方','めかた','무게; 중량','物の重さ。','荷物は見た目より目方があり、一人では持ち上げられなかった。','짐은 보기보다 무게가 나가 혼자서는 들 수 없었다.'),
('n1-1687','2026-12-09','英字','えいじ','영문자; 알파벳 문자','英語で用いるアルファベットの文字。','パスワードには英字と数字を組み合わせてください。','비밀번호에는 영문자와 숫자를 조합해 주세요.'),
('n1-1688','2026-12-09','誤差','ごさ','오차','測定値・計算値などと、本来の正確な値との差。','この測定器には数ミリ程度の誤差が生じる可能性がある。','이 측정기에는 수 밀리미터 정도의 오차가 생길 가능성이 있다.'),
('n1-1689','2026-12-09','切れ目','きれめ','끊어진 부분; 틈; 구분되는 지점','続いていたものが切れる箇所。また、物事の区切り・途切れる時点。','作業の切れ目を見て休憩を取ることにした。','작업이 끊기는 시점을 보고 휴식을 취하기로 했다.');
INSERT INTO japanese_words(word,reading,meaning_ko,meaning_ja,jlpt_level_id,ai_status,note) SELECT s.word,s.reading,s.meaning_ko,s.meaning_ja,(SELECT id FROM jlpt_levels WHERE code='N1'),'reviewed','JLPT N1 batch 2026-11-26..2026-12-09' FROM _n1_b5_words_0106 s WHERE NOT EXISTS (SELECT 1 FROM japanese_words w WHERE w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL);
INSERT INTO _n1_b5_map_0106(source_key,word_id) SELECT s.source_key,MIN(w.id) FROM _n1_b5_words_0106 s JOIN japanese_words w ON w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL GROUP BY s.source_key;
