INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2740","prompt":"「群がる」の読み方として最も適切なものを選びなさい。","options":["かわいがる","なまる","はげる","むらがる"],"answer":"むらがる","explanationKo":"「群がる」는 「むらがる」라고 읽는다. 뜻은 떼 지어 몰려들다; 무리를 이루어 모이다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2742","prompt":"「躓く」の読み方として最も適切なものを選びなさい。","options":["かわいがる","なまる","つまずく","すえつける"],"answer":"つまずく","explanationKo":"「躓く」는 「つまずく」라고 읽는다. 뜻은 발이 걸려 넘어질 뻔하다; 좌절하다; 일이 막히다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2744","prompt":"「打ち合わせる」の読み方として最も適切なものを選びなさい。","options":["ばてる","うちあわせる","はいけい","いかる"],"answer":"うちあわせる","explanationKo":"「打ち合わせる」는 「うちあわせる」라고 읽는다. 뜻은 협의하다; 사전 조율하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-2739","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n毎回同じ情報を入力するのは（　）。","options":["煩わしい","整然","気障","大ざっぱ"],"answer":"煩わしい","explanationKo":"문맥상 「煩わしい」가 가장 자연스럽다. 번거롭다; 성가시다; 귀찮다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-2751","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長く練習しないと感覚が（　）。","options":["盛る","意気込む","汚れる","鈍る"],"answer":"鈍る","explanationKo":"문맥상 「鈍る」가 가장 자연스럽다. 무뎌지다; 둔해지다; 능력이 떨어지다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2752","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n青空に白い建物がよく（　）。","options":["群がる","剥げる","映える","可愛がる"],"answer":"映える","explanationKo":"문맥상 「映える」가 가장 자연스럽다. 돋보이다; 빛나다; 잘 어울리다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-2754","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n猫は（　）な動きで塀の上に飛び乗った。","options":["所謂","しなやか","是非とも","情け深い"],"answer":"しなやか","explanationKo":"문맥상 「しなやか」가 가장 자연스럽다. 유연하다; 부드럽고 탄력 있다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-2767","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は困っている人を放っておけない（　）人だ。","options":["情け深い","真に","正しく","長々"],"answer":"情け深い","explanationKo":"문맥상 「情け深い」가 가장 자연스럽다. 인정이 많다; 자비롭다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-2793","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n初対面でそこまで頼むのは少し（　）。","options":["しなやか","馴れ馴れしい","整然","図々しい"],"answer":"図々しい","explanationKo":"문맥상 「図々しい」가 가장 자연스럽다. 뻔뻔하다; 염치없다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-2796","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は問題の原因を（　）指摘した。","options":["厭らしい","情け深い","ずばり","貴い"],"answer":"ずばり","explanationKo":"문맥상 「ずばり」가 가장 자연스럽다. 딱 잘라; 정곡을 찔러; 단도직입적으로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2758","prompt":"「機械・設備などを動かないように一定の場所へ取り付ける。」という意味に最も近い語を選びなさい。","options":["意気込む","据え付ける","活ける","冷やかす"],"answer":"据え付ける","explanationKo":"「据え付ける」의 핵심 의미는 설치하다; 고정해서 달다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2772","prompt":"「縫い目などがほどけて開く。また、つぼみや表情が開くようにほぐれる。」という意味に最も近い語を選びなさい。","options":["綻びる","躓く","活ける","冷やかす"],"answer":"綻びる","explanationKo":"「綻びる」의 핵심 의미는 솔기가 터지다; 벌어지다; 미소가 번지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2773","prompt":"「形・色・輪郭などがはっきりしなくなる。」という意味に最も近い語を選びなさい。","options":["恥じらう","躓く","活ける","ぼやける"],"answer":"ぼやける","explanationKo":"「ぼやける」의 핵심 의미는 흐려지다; 흐릿해지다; 초점이 모호해지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2777","prompt":"「やり方を誤って失敗する。」という意味に最も近い語を選びなさい。","options":["省みる","映える","しくじる","躓く"],"answer":"しくじる","explanationKo":"「しくじる」의 핵심 의미는 실수하다; 일을 망치다; 실패하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2803","prompt":"「表面の塗装・皮などが取れる。また、色が薄くなる。」という意味に最も近い語を選びなさい。","options":["恥じらう","剥げる","留める","据え付ける"],"answer":"剥げる","explanationKo":"「剥げる」의 핵심 의미는 벗겨지다; 칠이 벗겨지다; 색이 바래다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','grammar',1,'〜ものを','{"pattern":"〜ものを","meaningKo":"〜했으면 좋았을 텐데","explanation":"〜ものを는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"早く相談すれば解決できたものを、一人で抱え込んでしまった。","ko":"문맥에서 〜했으면 좋았을 텐데의 의미로 쓰였다."},{"ja":"黙っていれば疑われずに済んだものを、余計な説明を加えた。","ko":"이 문장도 〜했으면 좋았을 텐데의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','grammar',2,'〜ものと思われる','{"pattern":"〜ものと思われる","meaningKo":"〜일 것으로 생각된다","explanation":"〜ものと思われる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"調査結果は来月中に公表されるものと思われる。","ko":"문맥에서 〜일 것으로 생각된다의 의미로 쓰였다."},{"ja":"この傾向は当面続くものと思われる。","ko":"이 문장도 〜일 것으로 생각된다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n早く相談すれば解決できた（　）、一人で抱え込んでしまった。","options":["〜ものを","〜ないものか","〜を経て","〜にしたところで"],"answer":"〜ものを","explanationKo":"문맥상 〜했으면 좋았을 텐데를 나타내는 「〜ものを」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n調査結果は来月中に公表される（　）。","options":["〜を余儀なくされる","〜をめぐって","〜の至り","〜ものと思われる"],"answer":"〜ものと思われる","explanationKo":"문맥상 〜일 것으로 생각된다를 나타내는 「〜ものと思われる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n期限までに返答がなければ辞退した（　）扱う。","options":["〜を兼ねて","〜の極み","〜ものとして","〜を余儀なくさせる"],"answer":"〜ものとして","explanationKo":"문맥상 〜인 것으로 간주하여를 나타내는 「〜ものとして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-26','reading',1,'数値の背景を読む','{"passage":"統計の数値を解釈することには、変化の傾向を共通の基準で捉えられることという効果が期待できる。ただし、平均だけを見ると集団内の差を見落とすことにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、対象範囲と集計方法も併せて確認することが重要になる。","questions":[{"prompt":"「数値の背景を読む」について筆者が最も重視することは何か。","options":["対象範囲と集計方法も併せて確認すること","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"対象範囲と集計方法も併せて確認すること","explanationKo":"글쓴이는 対象範囲と集計方法も併せて確認すること 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["平均だけを見ると集団内の差を見落とすこと","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"平均だけを見ると集団内の差を見落とすこと","explanationKo":"주의할 점은 平均だけを見ると集団内の差を見落とすこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["変化の傾向を共通の基準で捉えられること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"変化の傾向を共通の基準で捉えられること","explanationKo":"統計の数値を解釈すること에는 変化の傾向を共通の基準で捉えられること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2869","prompt":"「可愛がる」の読み方として最も適切なものを選びなさい。","options":["かわいがる","ばてる","うちあわせる","おさまる"],"answer":"かわいがる","explanationKo":"「可愛がる」는 「かわいがる」라고 읽는다. 뜻은 귀여워하다; 아끼다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2922","prompt":"「尚」の読み方として最も適切なものを選びなさい。","options":["わずらわしい","まことに","きざ","なお"],"answer":"なお","explanationKo":"「尚」는 「なお」라고 읽는다. 뜻은 더욱; 여전히; 또한이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2930","prompt":"「恥じらう」の読み方として最も適切なものを選びなさい。","options":["しくじる","ばてる","はじらう","ひやかす"],"answer":"はじらう","explanationKo":"「恥じらう」는 「はじらう」라고 읽는다. 뜻은 수줍어하다; 부끄러워하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-2797","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n初対面なのに（　）話し方をされて戸惑った。","options":["尚","馴れ馴れしい","所謂","一人でに"],"answer":"馴れ馴れしい","explanationKo":"문맥상 「馴れ馴れしい」가 가장 자연스럽다. 지나치게 친한 척하다; 스스럼없다; 친한 체하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-2810","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n次回の会議には（　）参加してください。","options":["是非とも","図々しい","真に","長々"],"answer":"是非とも","explanationKo":"문맥상 「是非とも」가 가장 자연스럽다. 꼭; 반드시; 부디라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2812","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n高価な時計を（　）ような態度は好まれない。","options":["可愛がる","鈍る","剥げる","見せびらかす"],"answer":"見せびらかす","explanationKo":"문맥상 「見せびらかす」가 가장 자연스럽다. 과시하다; 자랑해 보이다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-2816","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）と説明してしまい、申し訳ありません。","options":["一人でに","ずばり","長々","情け深い"],"answer":"長々","explanationKo":"문맥상 「長々」가 가장 자연스럽다. 장황하게; 오래도록; 길게라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-2833","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n落とした皿が（　）に割れた。","options":["尚","粉々","真っ二つ","貴い"],"answer":"粉々","explanationKo":"문맥상 「粉々」가 가장 자연스럽다. 산산조각; 산산이라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-2846","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n人の弱みに付け込むような（　）やり方は嫌いだ。","options":["厭らしい","ずばり","馴れ馴れしい","所謂"],"answer":"厭らしい","explanationKo":"문맥상 「厭らしい」가 가장 자연스럽다. 불쾌하다; 야하다; 징그럽다; 노골적이다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-2855","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nまずは（　）な予定を決めよう。","options":["真に","兼ねて","粉々","大ざっぱ"],"answer":"大ざっぱ","explanationKo":"문맥상 「大ざっぱ」가 가장 자연스럽다. 대충이다; 대략적이다; 세세하지 않다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2931","prompt":"「疲れ切って力がなくなる。」という意味に最も近い語を選びなさい。","options":["群がる","ぼやける","ばてる","可愛がる"],"answer":"ばてる","explanationKo":"「ばてる」의 핵심 의미는 지치다; 기진맥진하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2972","prompt":"「疑いなく、まさにその通りであるさま。」という意味に最も近い語を選びなさい。","options":["情け深い","正しく","貴い","厭らしい"],"answer":"正しく","explanationKo":"「正しく」의 핵심 의미는 바로; 틀림없이; 과연이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2995","prompt":"「清らかさ・純粋さ・名誉などが失われる。」という意味に最も近い語を選びなさい。","options":["汚れる","ばてる","打ち合わせる","可愛がる"],"answer":"汚れる","explanationKo":"「汚れる」의 핵심 의미는 더럽혀지다; 오염되다; 명예가 훼손되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1306","prompt":"「話し手・聞き手から離れた場所・方向・人を丁寧に指す語。」という意味に最も近い語を選びなさい。","options":["私用","防火","再発","彼方"],"answer":"彼方","explanationKo":"「彼方」의 핵심 의미는 저쪽; 저곳; 저분이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2866","prompt":"「二つ以上の事柄を同時に行うさま。また、以前から。」という意味に最も近い語を選びなさい。","options":["ずばり","生温い","兼ねて","一人でに"],"answer":"兼ねて","explanationKo":"「兼ねて」의 핵심 의미는 겸하여; 동시에; 예전부터이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','grammar',1,'〜ものとして','{"pattern":"〜ものとして","meaningKo":"〜인 것으로 간주하여","explanation":"〜ものとして는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"申請者は規則に同意したものとして手続きを進める。","ko":"문맥에서 〜인 것으로 간주하여의 의미로 쓰였다."},{"ja":"期限までに返答がなければ辞退したものとして扱う。","ko":"이 문장도 〜인 것으로 간주하여의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','grammar',2,'〜ものなら','{"pattern":"〜ものなら","meaningKo":"만약 〜할 수 있다면","explanation":"〜ものなら는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"やり直せるものなら、最初から慎重に判断したい。","ko":"문맥에서 만약 〜할 수 있다면의 의미로 쓰였다."},{"ja":"本人に聞けるものなら、真意を確かめたい。","ko":"이 문장도 만약 〜할 수 있다면의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n申請者は規則に同意した（　）手続きを進める。","options":["〜を余儀なくさせる","〜を兼ねて","〜の極み","〜ものとして"],"answer":"〜ものとして","explanationKo":"문맥상 〜인 것으로 간주하여를 나타내는 「〜ものとして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nやり直せる（　）、最初から慎重に判断したい。","options":["〜に即した","〜とあっては","〜ものなら","〜をもって"],"answer":"〜ものなら","explanationKo":"문맥상 만약 〜할 수 있다면를 나타내는 「〜ものなら」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n参加を承諾した（　）、日程の調整がつかない。","options":["〜ときている","〜ものの","〜をもってしても","〜に先んじて"],"answer":"〜ものの","explanationKo":"문맥상 〜하기는 했지만를 나타내는 「〜ものの」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-27','reading',1,'例外を記録する意味','{"passage":"通常手順から外れた対応を記録することには、同じ状況が起きた際の判断材料になることという効果が期待できる。ただし、例外を安易に一般化すると手順が曖昧になることにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、適用した条件と理由を明記することが重要になる。","questions":[{"prompt":"「例外を記録する意味」について筆者が最も重視することは何か。","options":["適用した条件と理由を明記すること","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"適用した条件と理由を明記すること","explanationKo":"글쓴이는 適用した条件と理由を明記すること 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["例外を安易に一般化すると手順が曖昧になること","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"例外を安易に一般化すると手順が曖昧になること","explanationKo":"주의할 점은 例外を安易に一般化すると手順が曖昧になること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["同じ状況が起きた際の判断材料になること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"同じ状況が起きた際の判断材料になること","explanationKo":"通常手順から外れた対応を記録すること에는 同じ状況が起きた際の判断材料になること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2927","prompt":"「拝啓」の読み方として最も適切なものを選びなさい。","options":["けがれる","はいけい","はげる","むらがる"],"answer":"はいけい","explanationKo":"「拝啓」는 「はいけい」라고 읽는다. 뜻은 삼가 아룁니다; 존경하는 ~께이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
