INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2939","prompt":"「冷やかす」の読み方として最も適切なものを選びなさい。","options":["はいけい","ぼやける","はじらう","ひやかす"],"answer":"ひやかす","explanationKo":"「冷やかす」는 「ひやかす」라고 읽는다. 뜻은 놀리다; 야유하다; 구경만 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-2946","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nご協力いただき、（　）ありがとうございます。","options":["生温い","大ざっぱ","真に","ずばり"],"answer":"真に","explanationKo":"문맥상 「真に」가 가장 자연스럽다. 참으로; 정말로; 진실로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
