INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2989","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n春になると多くの花が（　）。","options":["盛る","ばてる","打ち合わせる","納まる"],"answer":"盛る","explanationKo":"문맥상 「盛る」가 가장 자연스럽다. 번성하다; 한창이다; 동물이 발정하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-2992","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n資料が棚に（　）と並べられている。","options":["厭らしい","馴れ馴れしい","しなやか","整然"],"answer":"整然","explanationKo":"문맥상 「整然」가 가장 자연스럽다. 정연함; 질서정연함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0702","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n事業の（　）を毎月確認し、赤字が続く部門の原因を分析している。","options":["疑惑","禁物","収支","市街"],"answer":"収支","explanationKo":"문맥상 「収支」가 가장 자연스럽다. 수지; 수입과 지출라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0703","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n報告書では市場の現状だけでなく、今後五年間の（　）についても述べている。","options":["勧誘","展望","強行","燃焼"],"answer":"展望","explanationKo":"문맥상 「展望」가 가장 자연스럽다. 전망; 앞날에 대한 예상; 조망라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0705","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n既存技術を組み合わせただけでなく、（　）的な発想を加えた点が高く評価された。","options":["独創","寄贈","土台","意図"],"answer":"独創","explanationKo":"문맥상 「独創」가 가장 자연스럽다. 독창; 새로운 것을 독자적으로 만들어 냄라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2530","prompt":"「一つの物事に心を強くとらわれ、そこから離れられないこと。」という意味に最も近い語を選びなさい。","options":["弾力","打撃","真相","執着"],"answer":"執着","explanationKo":"「執着」의 핵심 의미는 집착; 미련; 한 대상에 얽매임이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0713","prompt":"「心の中に抱いている感情・思い。」という意味に最も近い語を選びなさい。","options":["改修","指図","心情","辞職"],"answer":"心情","explanationKo":"「心情」의 핵심 의미는 심정; 마음속 감정이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0714","prompt":"「ある言語・分野・個人などが用いる単語の総体。」という意味に最も近い語を選びなさい。","options":["勧誘","語彙","強行","燃焼"],"answer":"語彙","explanationKo":"「語彙」의 핵심 의미는 어휘; 단어의 총체이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0722","prompt":"「物事の始めから終わりまで一貫していること。また、その間ずっと。」という意味に最も近い語を選びなさい。","options":["終始","奇数","再発","是正"],"answer":"終始","explanationKo":"「終始」의 핵심 의미는 시종; 처음부터 끝까지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0723","prompt":"「言動などから感じ取られる、その人の性質・品性・人となり。」という意味に最も近い語を選びなさい。","options":["内訳","云々","便宜","人柄"],"answer":"人柄","explanationKo":"「人柄」의 핵심 의미는 인품; 사람됨; 성품이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','grammar',1,'〜ものの','{"pattern":"〜ものの","meaningKo":"〜하기는 했지만","explanation":"〜ものの는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"改善策を導入したものの、十分な効果は得られなかった。","ko":"문맥에서 〜하기는 했지만의 의미로 쓰였다."},{"ja":"参加を承諾したものの、日程の調整がつかない。","ko":"이 문장도 〜하기는 했지만의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','grammar',2,'〜ないものか','{"pattern":"〜ないものか","meaningKo":"어떻게든 〜할 수 없을까","explanation":"〜ないものか는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"手続きをもう少し簡略化できないものか。","ko":"문맥에서 어떻게든 〜할 수 없을까의 의미로 쓰였다."},{"ja":"地域の負担を減らす方法はないものか。","ko":"이 문장도 어떻게든 〜할 수 없을까의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n改善策を導入した（　）、十分な効果は得られなかった。","options":["〜に先んじて","〜ときている","〜ものの","〜をもってしても"],"answer":"〜ものの","explanationKo":"문맥상 〜하기는 했지만를 나타내는 「〜ものの」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
