INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n資材不足により、生産規模の縮小（　）。","options":["〜を余儀なくされる","〜を経て","〜にまつわる","〜ならいざ知らず"],"answer":"〜を余儀なくされる","explanationKo":"문맥상 부득이 〜하게 되다를 나타내는 「〜を余儀なくされる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-28','reading',1,'選択肢を残す計画','{"passage":"複数の対応案を準備することには、状況の変化に応じて方針を切り替えられることという効果が期待できる。ただし、案を増やすだけでは判断が遅れることにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、切り替え条件と優先順位を先に決めることが重要になる。","questions":[{"prompt":"「選択肢を残す計画」について筆者が最も重視することは何か。","options":["切り替え条件と優先順位を先に決めること","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"切り替え条件と優先順位を先に決めること","explanationKo":"글쓴이는 切り替え条件と優先順位を先に決めること 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["案を増やすだけでは判断が遅れること","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"案を増やすだけでは判断が遅れること","explanationKo":"주의할 점은 案を増やすだけでは判断が遅れること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["状況の変化に応じて方針を切り替えられること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"状況の変化に応じて方針を切り替えられること","explanationKo":"複数の対応案を準備すること에는 状況の変化に応じて方針を切り替えられること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
