INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-0791","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその古典作品は、社会に追い詰められた男女の（　）を題材にしている。","options":["犠牲","心中","出題","応急"],"answer":"心中","explanationKo":"문맥상 「心中」가 가장 자연스럽다. 동반자살; 함께 자살함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0792","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n地震対策として、古い建物の柱を（　）する工事が進められている。","options":["補強","内訳","云々","便宜"],"answer":"補強","explanationKo":"문맥상 「補強」가 가장 자연스럽다. 보강; 강도를 높임라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0798","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n問い合わせの増加に対応するため、サポート要員を（　）した。","options":["下位","雑貨","浴室","増強"],"answer":"増強","explanationKo":"문맥상 「増強」가 가장 자연스럽다. 증강; 강화라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0800","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n売上低迷を（　）するため、会社は新しい市場への進出を決めた。","options":["鉛","書き取り","打開","修士"],"answer":"打開","explanationKo":"문맥상 「打開」가 가장 자연스럽다. 타개; 돌파구를 엶라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0802","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその雑誌は（　）から百年を迎え、記念号を発売した。","options":["賛美","創刊","防火","再発"],"answer":"創刊","explanationKo":"문맥상 「創刊」가 가장 자연스럽다. 창간라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0807","prompt":"「状態・雰囲気・状況などがすっかり変わること。また、変えること。」という意味に最も近い語を選びなさい。","options":["一変","吟味","妊娠","沈黙"],"answer":"一変","explanationKo":"「一変」의 핵심 의미는 일변; 완전히 바뀜이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0811","prompt":"「舞台で上演することを目的に、人物のせりふや動作を中心として書かれた文学作品。」という意味に最も近い語を選びなさい。","options":["疑惑","禁物","尻尾","戯曲"],"answer":"戯曲","explanationKo":"「戯曲」의 핵심 의미는 희곡이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0813","prompt":"「外交を担当する大臣。『外務大臣』の略称。」という意味に最も近い語を選びなさい。","options":["街頭","差額","外相","感度"],"answer":"外相","explanationKo":"「外相」의 핵심 의미는 외무상; 외교 담당 장관이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0818","prompt":"「成績・売上・活動などの勢いが上がらず、望ましい状態に達していないこと。」という意味に最も近い語を選びなさい。","options":["賛美","不振","光沢","調停"],"answer":"不振","explanationKo":"「不振」의 핵심 의미는 부진; 침체이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0826","prompt":"「便利で役に立つものとして大切に使うこと。また、非常に便利で役立つさま。」という意味に最も近い語を選びなさい。","options":["重宝","打撃","真相","普遍"],"answer":"重宝","explanationKo":"「重宝」의 핵심 의미는 매우 유용함; 소중히 여김이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','grammar',1,'〜を余儀なくされる','{"pattern":"〜を余儀なくされる","meaningKo":"부득이 〜하게 되다","explanation":"〜を余儀なくされる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"悪天候のため、計画の延期を余儀なくされた。","ko":"문맥에서 부득이 〜하게 되다의 의미로 쓰였다."},{"ja":"資材不足により、生産規模の縮小を余儀なくされた。","ko":"이 문장도 부득이 〜하게 되다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','grammar',2,'〜を余儀なくさせる','{"pattern":"〜を余儀なくさせる","meaningKo":"어쩔 수 없이 〜하게 만들다","explanation":"〜を余儀なくさせる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"急激な需要減少が企業に方針転換を余儀なくさせた。","ko":"문맥에서 어쩔 수 없이 〜하게 만들다의 의미로 쓰였다."},{"ja":"制度変更が現場に手順の見直しを余儀なくさせた。","ko":"이 문장도 어쩔 수 없이 〜하게 만들다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n悪天候のため、計画の延期（　）。","options":["〜ならいざ知らず","〜を余儀なくされる","〜を経て","〜にまつわる"],"answer":"〜を余儀なくされる","explanationKo":"문맥상 부득이 〜하게 되다를 나타내는 「〜を余儀なくされる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n急激な需要減少が企業に方針転換（　）。","options":["〜を余儀なくさせる","〜をめぐって","〜に言わせれば","〜にかかわらず"],"answer":"〜を余儀なくさせる","explanationKo":"문맥상 어쩔 수 없이 〜하게 만들다를 나타내는 「〜を余儀なくさせる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今回の報告（　）調査の完了とする。","options":["〜を兼ねて","〜にしたところで","〜を顧みず","〜をもって"],"answer":"〜をもって","explanationKo":"문맥상 〜을 기준으로; 〜로써를 나타내는 「〜をもって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-29','reading',1,'見えない負担を測る','{"passage":"制度利用に伴う負担を調べることには、表面上の成果だけでは分からない問題を発見できることという効果が期待できる。ただし、測定項目を増やしすぎると利用者の負担になることにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、目的に直結する負担を選んで継続的に見ることが重要になる。","questions":[{"prompt":"「見えない負担を測る」について筆者が最も重視することは何か。","options":["目的に直結する負担を選んで継続的に見ること","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"目的に直結する負担を選んで継続的に見ること","explanationKo":"글쓴이는 目的に直結する負担を選んで継続的に見ること 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["測定項目を増やしすぎると利用者の負担になること","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"測定項目を増やしすぎると利用者の負担になること","explanationKo":"주의할 점은 測定項目を増やしすぎると利用者の負担になること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["表面上の成果だけでは分からない問題を発見できること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"表面上の成果だけでは分からない問題を発見できること","explanationKo":"制度利用に伴う負担を調べること에는 表面上の成果だけでは分からない問題を発見できること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0853","prompt":"「口頭」の読み方として最も適切なものを選びなさい。","options":["ざっか","よくしつ","にくしみ","こうとう"],"answer":"こうとう","explanationKo":"「口頭」는 「こうとう」라고 읽는다. 뜻은 구두; 말로 함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
