INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0871","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n都市と農村の生活を（　）することで、地域ごとの課題が見えてくる。","options":["共存","対比","吟味","襲撃"],"answer":"対比","explanationKo":"문맥상 「対比」가 가장 자연스럽다. 대비; 대조라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-0879","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新駅の開業をきっかけに、（　）の住宅開発が進んでいる。","options":["沿線","真相","普遍","断面"],"answer":"沿線","explanationKo":"문맥상 「沿線」가 가장 자연스럽다. 철도 노선 연변; 노선 주변라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-0880","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n試作品は機能だけでなく、外観の（　）も高く評価された。","options":["驚異","尿","愛憎","仕上がり"],"answer":"仕上がり","explanationKo":"문맥상 「仕上がり」가 가장 자연스럽다. 완성된 상태; 마무리 품질라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-0882","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの作品の（　）は現在では入手が難しく、古書市場で高値が付いている。","options":["異動","代弁","初版","模範"],"answer":"初版","explanationKo":"문맥상 「初版」가 가장 자연스럽다. 초판라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0886","prompt":"「二つの物事を、どちらも損なわず同時に成り立たせること。」という意味に最も近い語を選びなさい。","options":["行き違い","両立","云々","便宜"],"answer":"両立","explanationKo":"「両立」의 핵심 의미는 양립; 두 가지를 함께 성립시킴이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0899","prompt":"「条約・協定などの正式な文書に、当事者が署名すること。」という意味に最も近い語を選びなさい。","options":["調印","雑貨","浴室","憎しみ"],"answer":"調印","explanationKo":"「調印」의 핵심 의미는 조인; 서명 체결이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0903","prompt":"「二人ほどの人が、特定のテーマについて向かい合って話し合うこと。」という意味に最も近い語を選びなさい。","options":["鉛","書き取り","暗示","対談"],"answer":"対談","explanationKo":"「対談」의 핵심 의미는 대담; 서로 마주 보고 이야기함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0905","prompt":"「物理的に同じ振動数で響き合うこと。また比喩的に、他人の思想・感情に強く共感すること。」という意味に最も近い語を選びなさい。","options":["是正","避難","共鳴","再発"],"answer":"共鳴","explanationKo":"「共鳴」의 핵심 의미는 공명; 깊이 공감함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0915","prompt":"「あらかじめ定められた日。ある事を行う期限・予定の日。」という意味に最も近い語を選びなさい。","options":["均衡","期日","一筋","黒字"],"answer":"期日","explanationKo":"「期日」의 핵심 의미는 기일; 정해진 날짜이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','grammar',1,'〜をもって','{"pattern":"〜をもって","meaningKo":"〜을 기준으로; 〜로써","explanation":"〜をもって는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"本日をもって受付を終了いたします。","ko":"문맥에서 〜을 기준으로; 〜로써의 의미로 쓰였다."},{"ja":"今回の報告をもって調査の完了とする。","ko":"이 문장도 〜을 기준으로; 〜로써의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','grammar',2,'〜をもってしても','{"pattern":"〜をもってしても","meaningKo":"〜을 가지고도","explanation":"〜をもってしても는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"最新の技術をもってしても、完全な予測は難しい。","ko":"문맥에서 〜을 가지고도의 의미로 쓰였다."},{"ja":"専門家の知識をもってしても、原因を特定できなかった。","ko":"이 문장도 〜을 가지고도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n本日（　）受付を終了いたします。","options":["〜をもって","〜を兼ねて","〜にしたところで","〜を顧みず"],"answer":"〜をもって","explanationKo":"문맥상 〜을 기준으로; 〜로써를 나타내는 「〜をもって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n最新の技術（　）、完全な予測は難しい。","options":["〜に即した","〜の至り","〜ものを","〜をもってしても"],"answer":"〜をもってしても","explanationKo":"문맥상 〜을 가지고도를 나타내는 「〜をもってしても」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n過去の失敗（　）、新たな基準を設ける。","options":["〜の極み","〜ものと思われる","〜を踏まえて","〜に先んじて"],"answer":"〜を踏まえて","explanationKo":"문맥상 〜을 토대로를 나타내는 「〜を踏まえて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-11-30','reading',1,'反対意見との向き合い方','{"passage":"反対意見の根拠を検討することには、計画の弱点や不足条件を見つけられることという効果が期待できる。ただし、相手を説得することだけが目的になることにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、主張とその前提を分けて確かめることが重要になる。","questions":[{"prompt":"「反対意見との向き合い方」について筆者が最も重視することは何か。","options":["主張とその前提を分けて確かめること","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"主張とその前提を分けて確かめること","explanationKo":"글쓴이는 主張とその前提を分けて確かめること 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["相手を説得することだけが目的になること","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"相手を説得することだけが目的になること","explanationKo":"주의할 점은 相手を説得することだけが目的になること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["計画の弱点や不足条件を見つけられること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"計画の弱点や不足条件を見つけられること","explanationKo":"反対意見の根拠を検討すること에는 計画の弱点や不足条件を見つけられること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-01','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0967","prompt":"「所謂」の読み方として最も適切なものを選びなさい。","options":["いわゆる","たっとい","なお","ながなが"],"answer":"いわゆる","explanationKo":"「所謂」는 「いわゆる」라고 읽는다. 뜻은 이른바; 소위이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
