INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-01','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1030","prompt":"「犠牲」の読み方として最も適切なものを選びなさい。","options":["かくさ","おちつき","ぎせい","いと"],"answer":"ぎせい","explanationKo":"「犠牲」는 「ぎせい」라고 읽는다. 뜻은 희생; 희생자이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-01','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1036","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの地域では気候を生かして高品質なぶどうを（　）している。","options":["沈没","栽培","短縮","弁解"],"answer":"栽培","explanationKo":"문맥상 「栽培」가 가장 자연스럽다. 재배라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
