INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-01','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1091","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n避難所には最大で五百人を（　）できる設備が整っている。","options":["黒字","均衡","収容","一筋"],"answer":"収容","explanationKo":"문맥상 「収容」가 가장 자연스럽다. 수용; 시설 등에 넣음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-01','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1098","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n責任を取る形で社長が（　）する意向を表明した。","options":["磁器","辞職","禁物","尻尾"],"answer":"辞職","explanationKo":"문맥상 「辞職」가 가장 자연스럽다. 사직; 직책에서 물러남라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-01','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1104","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n突然の発表は業界全体に大きな（　）を与えた。","options":["衝撃","購買","降水","引き分け"],"answer":"衝撃","explanationKo":"문맥상 「衝撃」가 가장 자연스럽다. 충격; 쇼크라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
