INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-01','grammar',2,'〜を経て','{"pattern":"〜を経て","meaningKo":"〜을 거쳐","explanation":"〜を経て는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"長い協議を経て、双方が合意に達した。","ko":"문맥에서 〜을 거쳐의 의미로 쓰였다."},{"ja":"複数回の試験を経て、製品化が決まった。","ko":"이 문장도 〜을 거쳐의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-01','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n利用者の意見（　）、設計を見直した。","options":["〜に先んじて","〜の極み","〜ものと思われる","〜を踏まえて"],"answer":"〜を踏まえて","explanationKo":"문맥상 〜을 토대로를 나타내는 「〜を踏まえて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-01','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長い協議（　）、双方が合意に達した。","options":["〜とあっては","〜ものとして","〜を経て","〜にとどまらず"],"answer":"〜を経て","explanationKo":"문맥상 〜을 거쳐를 나타내는 「〜を経て」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-01','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n土地の利用（　）、住民と事業者が協議した。","options":["〜ものなら","〜をめぐって","〜にまつわる","〜ときている"],"answer":"〜をめぐって","explanationKo":"문맥상 〜을 둘러싸고를 나타내는 「〜をめぐって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-01','reading',1,'技術を使わない判断','{"passage":"便利な技術の利用可否を判断することには、目的に合わない費用や複雑さを避けられることという効果が期待できる。ただし、新しい技術を拒むこと自体が目的になることにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、導入効果と維持負担を同じ基準で比べることが重要になる。","questions":[{"prompt":"「技術を使わない判断」について筆者が最も重視することは何か。","options":["導入効果と維持負担を同じ基準で比べること","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"導入効果と維持負担を同じ基準で比べること","explanationKo":"글쓴이는 導入効果と維持負担を同じ基準で比べること 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["新しい技術を拒むこと自体が目的になること","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"新しい技術を拒むこと自体が目的になること","explanationKo":"주의할 점은 新しい技術を拒むこと自体が目的になること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["目的に合わない費用や複雑さを避けられること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"目的に合わない費用や複雑さを避けられること","explanationKo":"便利な技術の利用可否を判断すること에는 目的に合わない費用や複雑さを避けられること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1151","prompt":"「小売」の読み方として最も適切なものを選びなさい。","options":["こうとう","こうり","はんらん","しゅっぴ"],"answer":"こうり","explanationKo":"「小売」는 「こうり」라고 읽는다. 뜻은 소매이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1152","prompt":"「赴任」の読み方として最も適切なものを選びなさい。","options":["ふにん","がいしょう","しょうげき","てじょう"],"answer":"ふにん","explanationKo":"「赴任」는 「ふにん」라고 읽는다. 뜻은 부임이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1167","prompt":"「奨励」の読み方として最も適切なものを選びなさい。","options":["しそく","しょくん","ひめい","しょうれい"],"answer":"しょうれい","explanationKo":"「奨励」는 「しょうれい」라고 읽는다. 뜻은 장려이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1171","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n調査員は（　）して海底の設備を点検した。","options":["断面","庶務","潜水","普遍"],"answer":"潜水","explanationKo":"문맥상 「潜水」가 가장 자연스럽다. 잠수라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
