INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1189","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長年続いた派閥間の（　）が組織の弱体化を招いた。","options":["仕掛け","抗争","降水","引き分け"],"answer":"抗争","explanationKo":"문맥상 「抗争」가 가장 자연스럽다. 항쟁; 세력 간의 격렬한 다툼라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1192","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n講演の（　）で、講師は研究の目的を簡潔に説明した。","options":["冒頭","暗示","対比","赴任"],"answer":"冒頭","explanationKo":"문맥상 「冒頭」가 가장 자연스럽다. 서두; 맨 처음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1197","prompt":"「勢力・人気・能力などが最も盛んな状態。」という意味に最も近い語を選びなさい。","options":["削減","忠告","手分け","全盛"],"answer":"全盛","explanationKo":"「全盛」의 핵심 의미는 전성; 가장 번성한 상태이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1199","prompt":"「他人の成功・能力・愛情などをうらやみ、ねたむ気持ち。」という意味に最も近い語を選びなさい。","options":["磁器","目方","嫉妬","尻尾"],"answer":"嫉妬","explanationKo":"「嫉妬」의 핵심 의미는 질투이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1200","prompt":"「世間に対する体面・名誉。また、人や物事の本来の姿・価値。」という意味に最も近い語を選びなさい。","options":["仕掛け","面目","降水","引き分け"],"answer":"面目","explanationKo":"「面目」의 핵심 의미는 면목; 체면; 명예이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1202","prompt":"「建物・商店・道路などが集中している都市の区域。」という意味に最も近い語を選びなさい。","options":["市街","消息","手錠","万人"],"answer":"市街","explanationKo":"「市街」의 핵심 의미는 시가지; 도심의 건물이 밀집한 지역이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1208","prompt":"「ある状態・作用などが途切れずに続くこと。また、続けて保つこと。」という意味に最も近い語を選びなさい。","options":["共存","控除","同封","持続"],"answer":"持続","explanationKo":"「持続」의 핵심 의미는 지속이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','grammar',1,'〜をめぐって','{"pattern":"〜をめぐって","meaningKo":"〜을 둘러싸고","explanation":"〜をめぐって는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"新制度の是非をめぐって、活発な議論が続いている。","ko":"문맥에서 〜을 둘러싸고의 의미로 쓰였다."},{"ja":"土地の利用をめぐって、住民と事業者が協議した。","ko":"이 문장도 〜을 둘러싸고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','grammar',2,'〜を兼ねて','{"pattern":"〜を兼ねて","meaningKo":"〜을 겸하여","explanation":"〜を兼ねて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"現地調査を兼ねて、関係者を訪問した。","ko":"문맥에서 〜을 겸하여의 의미로 쓰였다."},{"ja":"運動を兼ねて、毎朝駅まで歩いている。","ko":"이 문장도 〜을 겸하여의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
