INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-02','reading',1,'途中結果の公開','{"passage":"計画途中の結果を共有することには、問題を早い段階で発見し修正できることという効果が期待できる。ただし、未確定の内容が結論として受け取られることにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、暫定結果である範囲と今後の確認事項を示すことが重要になる。","questions":[{"prompt":"「途中結果の公開」について筆者が最も重視することは何か。","options":["暫定結果である範囲と今後の確認事項を示すこと","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"暫定結果である範囲と今後の確認事項を示すこと","explanationKo":"글쓴이는 暫定結果である範囲と今後の確認事項を示すこと 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["未確定の内容が結論として受け取られること","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"未確定の内容が結論として受け取られること","explanationKo":"주의할 점은 未確定の内容が結論として受け取られること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["問題を早い段階で発見し修正できること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"問題を早い段階で発見し修正できること","explanationKo":"計画途中の結果を共有すること에는 問題を早い段階で発見し修正できること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
