INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-03','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1278","prompt":"「多くの人・生物・物などが一か所に集まること。また、その集まり。」という意味に最も近い語を選びなさい。","options":["心中","対談","群集","下火"],"answer":"群集","explanationKo":"「群集」의 핵심 의미는 군집; 집단이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
