INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-03','grammar',1,'〜に即した','{"pattern":"〜に即した","meaningKo":"〜에 부합하는","explanation":"〜に即した는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"現場の実情に即した支援策が求められる。","ko":"문맥에서 〜에 부합하는의 의미로 쓰였다."},{"ja":"利用目的に即した情報だけを提示すべきだ。","ko":"이 문장도 〜에 부합하는의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-03','grammar',2,'〜に先んじて','{"pattern":"〜に先んじて","meaningKo":"〜에 앞서","explanation":"〜に先んじて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"他社に先んじて、新しい安全基準を導入した。","ko":"문맥에서 〜에 앞서의 의미로 쓰였다."},{"ja":"本格運用に先んじて、小規模な試験を行う。","ko":"이 문장도 〜에 앞서의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-03','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n現場の実情（　）支援策が求められる。","options":["〜ないものか","〜に即した","〜にしたところで","〜ならいざ知らず"],"answer":"〜に即した","explanationKo":"문맥상 〜에 부합하는를 나타내는 「〜に即した」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-03','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n他社（　）、新しい安全基準を導入した。","options":["〜に先んじて","〜の至り","〜にかかわらず","〜を余儀なくされる"],"answer":"〜に先んじて","explanationKo":"문맥상 〜에 앞서를 나타내는 「〜に先んじて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-03','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの技術は医療（　）、教育にも応用されている。","options":["〜の極み","〜を顧みず","〜を余儀なくさせる","〜にとどまらず"],"answer":"〜にとどまらず","explanationKo":"문맥상 〜에 그치지 않고를 나타내는 「〜にとどまらず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-03','reading',1,'利用者の声の扱い','{"passage":"利用者から意見を集めることには、提供側が気づかない不便を把握できることという効果が期待できる。ただし、声の大きい少数の意見に偏ることにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、意見の背景と利用状況を併せて分析することが重要になる。","questions":[{"prompt":"「利用者の声の扱い」について筆者が最も重視することは何か。","options":["意見の背景と利用状況を併せて分析すること","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"意見の背景と利用状況を併せて分析すること","explanationKo":"글쓴이는 意見の背景と利用状況を併せて分析すること 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["声の大きい少数の意見に偏ること","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"声の大きい少数の意見に偏ること","explanationKo":"주의할 점은 声の大きい少数の意見に偏ること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["提供側が気づかない不便を把握できること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"提供側が気づかない不便を把握できること","explanationKo":"利用者から意見を集めること에는 提供側が気づかない不便を把握できること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-04','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1304","prompt":"「下位」の読み方として最も適切なものを選びなさい。","options":["しょむ","えいじ","ぞうきょう","かい"],"answer":"かい","explanationKo":"「下位」는 「かい」라고 읽는다. 뜻은 하위; 낮은 순위이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
