INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-04','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1340","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n指導者は若者たちに向かって『（　）の挑戦に期待する』と語った。","options":["奨励","納入","諸君","両立"],"answer":"諸君","explanationKo":"문맥상 「諸君」가 가장 자연스럽다. 제군; 여러분라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-04','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1346","prompt":"「感情や態度が安定していて、慌てず静かであること。」という意味に最も近い語を選びなさい。","options":["修了","落ち着き","消去","奮闘"],"answer":"落ち着き","explanationKo":"「落ち着き」의 핵심 의미는 침착함; 차분함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-04','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1348","prompt":"「反対・困難・危険などがあっても、予定や方針を押し切って実行すること。」という意味に最も近い語を選びなさい。","options":["強行","庶務","英字","増強"],"answer":"強行","explanationKo":"「強行」의 핵심 의미는 강행; 무리하게 실행함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-04','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1350","prompt":"「海軍に所属し、戦闘・警戒などの軍事目的で用いられる船。」という意味に最も近い語を選びなさい。","options":["口頭","織物","前途","軍艦"],"answer":"軍艦","explanationKo":"「軍艦」의 핵심 의미는 군함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-04','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1352","prompt":"「医師が患者を診察し、必要な治療を行うこと。」という意味に最も近い語を選びなさい。","options":["休戦","墜落","診療","小売"],"answer":"診療","explanationKo":"「診療」의 핵심 의미는 진료이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-04','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1354","prompt":"「相手を価値の低いものと見て、見下し尊重しないこと。」という意味に最も近い語を選びなさい。","options":["待望","軽蔑","手分け","封鎖"],"answer":"軽蔑","explanationKo":"「軽蔑」의 핵심 의미는 경멸; 업신여김이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-04','grammar',1,'〜にとどまらず','{"pattern":"〜にとどまらず","meaningKo":"〜에 그치지 않고","explanation":"〜にとどまらず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"影響は国内にとどまらず、海外にも広がった。","ko":"문맥에서 〜에 그치지 않고의 의미로 쓰였다."},{"ja":"この技術は医療にとどまらず、教育にも応用されている。","ko":"이 문장도 〜에 그치지 않고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-04','grammar',2,'〜にまつわる','{"pattern":"〜にまつわる","meaningKo":"〜에 얽힌","explanation":"〜にまつわる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"この地域には湖にまつわる伝説が残っている。","ko":"문맥에서 〜에 얽힌의 의미로 쓰였다."},{"ja":"研究者は発見にまつわる経緯を詳しく語った。","ko":"이 문장도 〜에 얽힌의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-04','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n影響は国内（　）、海外にも広がった。","options":["〜にとどまらず","〜の極み","〜を顧みず","〜を余儀なくさせる"],"answer":"〜にとどまらず","explanationKo":"문맥상 〜에 그치지 않고를 나타내는 「〜にとどまらず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-04','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの地域には湖（　）伝説が残っている。","options":["〜とあっては","〜ものを","〜をもって","〜にまつわる"],"answer":"〜にまつわる","explanationKo":"문맥상 〜에 얽힌를 나타내는 「〜にまつわる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-04','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼（　）、準備不足こそ最大の原因らしい。","options":["〜ものと思われる","〜をもってしても","〜に言わせれば","〜ときている"],"answer":"〜に言わせれば","explanationKo":"문맥상 〜의 말에 따르면를 나타내는 「〜に言わせれば」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-04','reading',1,'長期目標の分け方','{"passage":"長期目標を短い段階に分けることには、進捗と問題点を途中で確認できることという効果が期待できる。ただし、短期成果だけを追うと本来の目的を失うことにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、各段階が最終目標にどう結び付くか示すことが重要になる。","questions":[{"prompt":"「長期目標の分け方」について筆者が最も重視することは何か。","options":["各段階が最終目標にどう結び付くか示すこと","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"各段階が最終目標にどう結び付くか示すこと","explanationKo":"글쓴이는 各段階が最終目標にどう結び付くか示すこと 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["短期成果だけを追うと本来の目的を失うこと","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"短期成果だけを追うと本来の目的を失うこと","explanationKo":"주의할 점은 短期成果だけを追うと本来の目的を失うこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["進捗と問題点を途中で確認できること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"進捗と問題点を途中で確認できること","explanationKo":"長期目標を短い段階に分けること에는 進捗と問題点を途中で確認できること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1387","prompt":"「傍ら」の読み方として最も適切なものを選びなさい。","options":["かたわら","こうじゅつ","はんかん","さぎ"],"answer":"かたわら","explanationKo":"「傍ら」는 「かたわら」라고 읽는다. 뜻은 곁; 한편으로는; ~하는 한편이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
