INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1400","prompt":"「海峡」の読み方として最も適切なものを選びなさい。","options":["たてまえ","こたい","かいきょう","ぐんかん"],"answer":"かいきょう","explanationKo":"「海峡」는 「かいきょう」라고 읽는다. 뜻은 해협이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1408","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n豊かな水の（　）によって、この地域では農業が発展してきた。","options":["展望","恵み","名札","行員"],"answer":"恵み","explanationKo":"문맥상 「恵み」가 가장 자연스럽다. 은혜; 혜택; 자연이 주는 혜택라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1412","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）部では昼夜の気温差が大きくなることがある。","options":["内陸","英字","増強","増進"],"answer":"内陸","explanationKo":"문맥상 「内陸」가 가장 자연스럽다. 내륙라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1419","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n給与から社会保険料などが（　）された後の金額が振り込まれる。","options":["皇居","傍ら","金槌","控除"],"answer":"控除","explanationKo":"문맥상 「控除」가 가장 자연스럽다. 공제; 일정 금액을 빼는 것라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1425","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n大学で学んだ統計の知識が、現在の分析業務の（　）になっている。","options":["中和","脚色","下地","休戦"],"answer":"下地","explanationKo":"문맥상 「下地」가 가장 자연스럽다. 밑바탕; 기초; 소질라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1428","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n時間がないので、資料確認と会場準備を（　）して進めよう。","options":["打開","手分け","眼科","誤差"],"answer":"手分け","explanationKo":"문맥상 「手分け」가 가장 자연스럽다. 분담; 일을 나누어 맡음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1429","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n同じ意味の単語でも、文脈によって（　）が少し異なる。","options":["ニュアンス","自我","見込み","延べ"],"answer":"ニュアンス","explanationKo":"문맥상 「ニュアンス」가 가장 자연스럽다. 뉘앙스; 미묘한 어감·느낌라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1430","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n条約では（　）の人道的な取り扱いについて定めている。","options":["皇居","傍ら","寒気","捕虜"],"answer":"捕虜","explanationKo":"문맥상 「捕虜」가 가장 자연스럽다. 포로; 전쟁 포로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
