INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1452","prompt":"「航空機・物体・人などが高い所から急激に落ちること。」という意味に最も近い語を選びなさい。","options":["万人","建前","固体","墜落"],"answer":"墜落","explanationKo":"「墜落」의 핵심 의미는 추락이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1462","prompt":"「航空機・船・大型機械などを操作して、思いどおりに動かすこと。」という意味に最も近い語を選びなさい。","options":["行員","展望","操縦","名札"],"answer":"操縦","explanationKo":"「操縦」의 핵심 의미는 조종; 운전이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','grammar',1,'〜に言わせれば','{"pattern":"〜に言わせれば","meaningKo":"〜의 말에 따르면","explanation":"〜に言わせれば는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"専門家に言わせれば、この変化は予想の範囲内だという。","ko":"문맥에서 〜의 말에 따르면의 의미로 쓰였다."},{"ja":"彼に言わせれば、準備不足こそ最大の原因らしい。","ko":"이 문장도 〜의 말에 따르면의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','grammar',2,'〜にしたところで','{"pattern":"〜にしたところで","meaningKo":"〜의 입장이라 해도","explanation":"〜にしたところで는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"責任者にしたところで、すべてを把握しているわけではない。","ko":"문맥에서 〜의 입장이라 해도의 의미로 쓰였다."},{"ja":"専門家にしたところで、未来を断言することはできない。","ko":"이 문장도 〜의 입장이라 해도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n専門家（　）、この変化は予想の範囲内だという。","options":["〜ときている","〜ものと思われる","〜をもってしても","〜に言わせれば"],"answer":"〜に言わせれば","explanationKo":"문맥상 〜의 말에 따르면를 나타내는 「〜に言わせれば」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n責任者（　）、すべてを把握しているわけではない。","options":["〜ものとして","〜を踏まえて","〜にしたところで","〜とみるや"],"answer":"〜にしたところで","explanationKo":"문맥상 〜의 입장이라 해도를 나타내는 「〜にしたところで」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n皆様にご迷惑をおかけし、恐縮（　）です。","options":["〜を経て","〜の至り","〜ならいざ知らず","〜ものなら"],"answer":"〜の至り","explanationKo":"문맥상 더없는 〜를 나타내는 「〜の至り」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-05','reading',1,'責任範囲を明確にする','{"passage":"共同作業の責任範囲を定めることには、問題発生時の確認先が分かりやすくなることという効果が期待できる。ただし、境界を厳格にしすぎると協力が妨げられることにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、担当と連携が必要な場面を同時に決めることが重要になる。","questions":[{"prompt":"「責任範囲を明確にする」について筆者が最も重視することは何か。","options":["担当と連携が必要な場面を同時に決めること","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"担当と連携が必要な場面を同時に決めること","explanationKo":"글쓴이는 担当と連携が必要な場面を同時に決めること 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["境界を厳格にしすぎると協力が妨げられること","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"境界を厳格にしすぎると協力が妨げられること","explanationKo":"주의할 점은 境界を厳格にしすぎると協力が妨げられること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["問題発生時の確認先が分かりやすくなること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"問題発生時の確認先が分かりやすくなること","explanationKo":"共同作業の責任範囲を定めること에는 問題発生時の確認先が分かりやすくなること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1488","prompt":"「均衡」の読み方として最も適切なものを選びなさい。","options":["さいばい","きんこう","ごさ","だかい"],"answer":"きんこう","explanationKo":"「均衡」는 「きんこう」라고 읽는다. 뜻은 균형; 평형이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1489","prompt":"「逃走」の読み方として最も適切なものを選びなさい。","options":["とうそう","たいぐう","へんけん","かんき"],"answer":"とうそう","explanationKo":"「逃走」는 「とうそう」라고 읽는다. 뜻은 도주; 달아남이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1496","prompt":"「悲鳴」の読み方として最も適切なものを選びなさい。","options":["はんしょく","ついらく","ししゅう","ひめい"],"answer":"ひめい","explanationKo":"「悲鳴」는 「ひめい」라고 읽는다. 뜻은 비명; 비유적으로 감당하기 힘든 호소이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1503","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n体調が悪くなった生徒は（　）教諭のいる保健室で休んだ。","options":["切れ目","創刊","養護","異性"],"answer":"養護","explanationKo":"문맥상 「養護」가 가장 자연스럽다. 양호; 보호·돌봄라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1506","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n春になると川沿いの（　）に多くの花が咲く。","options":["群集","土手","反感","詐欺"],"answer":"土手","explanationKo":"문맥상 「土手」가 가장 자연스럽다. 둑; 제방라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1510","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n燃料を完全に（　）させることで、有害物質の発生を抑える。","options":["燃焼","奨励","納入","操縦"],"answer":"燃焼","explanationKo":"문맥상 「燃焼」가 가장 자연스럽다. 연소라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1511","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）をこぼすだけでは状況は変わらないので、改善策を考えることにした。","options":["建前","固体","怪獣","愚痴"],"answer":"愚痴","explanationKo":"문맥상 「愚痴」가 가장 자연스럽다. 푸념; 불평라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1515","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n制度上の（　）と現場の実情が大きく食い違っている。","options":["展望","一変","建前","行員"],"answer":"建前","explanationKo":"문맥상 「建前」가 가장 자연스럽다. 겉으로 내세우는 원칙; 명분라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1518","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n私は（　）なので、海では必ず救命胴衣を着る。","options":["突破","金槌","増強","増進"],"answer":"金槌","explanationKo":"문맥상 「金槌」가 가장 자연스럽다. 쇠망치; 수영을 못하는 사람라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1521","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n窓を開けると強い（　）が室内に流れ込んできた。","options":["寒気","潜水","承諾","誘惑"],"answer":"寒気","explanationKo":"문맥상 「寒気」가 가장 자연스럽다. 한기; 찬 공기라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1522","prompt":"「時間・金銭・空間・気持ちなどに余裕があり、差し迫っていない状態。」という意味に最も近い語を選びなさい。","options":["中和","脚色","収支","ゆとり"],"answer":"ゆとり","explanationKo":"「ゆとり」의 핵심 의미는 여유; 여력이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1523","prompt":"「戦争・防衛に備えて整える兵器・施設・兵力などの軍事的な装備。」という意味に最も近い語を選びなさい。","options":["仕上がり","冒頭","軍備","舗装"],"answer":"軍備","explanationKo":"「軍備」의 핵심 의미는 군비; 군사 장비와 준비이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1525","prompt":"「両手などを地面につき、足を上にして体を逆さに立てること。」という意味に最も近い語を選びなさい。","options":["破棄","逆立ち","対談","賠償"],"answer":"逆立ち","explanationKo":"「逆立ち」의 핵심 의미는 물구나무서기이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1528","prompt":"「ある出来事・変化が起こりそうだと感じさせる気配。」という意味に最も近い語を選びなさい。","options":["兆し","傍ら","金槌","火花"],"answer":"兆し","explanationKo":"「兆し」의 핵심 의미는 조짐; 징조; 기미이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1529","prompt":"「商品・物品などを金銭を支払って買うこと。」という意味に最も近い語を選びなさい。","options":["修了","彼方","期日","購買"],"answer":"購買","explanationKo":"「購買」의 핵심 의미는 구매; 구입이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','grammar',1,'〜の至り','{"pattern":"〜の至り","meaningKo":"더없는 〜","explanation":"〜の至り는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"このような賞を頂き、光栄の至りです。","ko":"문맥에서 더없는 〜의 의미로 쓰였다."},{"ja":"皆様にご迷惑をおかけし、恐縮の至りです。","ko":"이 문장도 더없는 〜의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','grammar',2,'〜の極み','{"pattern":"〜の極み","meaningKo":"극도의 〜","explanation":"〜の極み는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"長年の努力が認められ、感激の極みだ。","ko":"문맥에서 극도의 〜의 의미로 쓰였다."},{"ja":"根拠なく非難するとは、無責任の極みである。","ko":"이 문장도 극도의 〜의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこのような賞を頂き、光栄（　）です。","options":["〜ものなら","〜を経て","〜の至り","〜ならいざ知らず"],"answer":"〜の至り","explanationKo":"문맥상 더없는 〜를 나타내는 「〜の至り」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長年の努力が認められ、感激（　）だ。","options":["〜をめぐって","〜の極み","〜にかかわらず","〜ものの"],"answer":"〜の極み","explanationKo":"문맥상 극도의 〜를 나타내는 「〜の極み」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n責任者の要請（　）、協力しないわけにはいかない。","options":["〜とあっては","〜を顧みず","〜ないものか","〜を兼ねて"],"answer":"〜とあっては","explanationKo":"문맥상 〜라면를 나타내는 「〜とあっては」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-06','reading',1,'情報を更新する基準','{"passage":"保存した情報を更新することには、古い条件による誤判断を減らせることという効果が期待できる。ただし、頻繁な更新がかえって変更点を見えにくくすることにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、有効期限と変更理由を記録することが重要になる。","questions":[{"prompt":"「情報を更新する基準」について筆者が最も重視することは何か。","options":["有効期限と変更理由を記録すること","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"有効期限と変更理由を記録すること","explanationKo":"글쓴이는 有効期限と変更理由を記録すること 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["頻繁な更新がかえって変更点を見えにくくすること","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"頻繁な更新がかえって変更点を見えにくくすること","explanationKo":"주의할 점은 頻繁な更新がかえって変更点を見えにくくすること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["古い条件による誤判断を減らせること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"古い条件による誤判断を減らせること","explanationKo":"保存した情報を更新すること에는 古い条件による誤判断を減らせること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1539","prompt":"「沈没」の読み方として最も適切なものを選びなさい。","options":["ぞうしん","とっぱ","ちんぼつ","ぞうきょう"],"answer":"ちんぼつ","explanationKo":"「沈没」는 「ちんぼつ」라고 읽는다. 뜻은 침몰; 가라앉음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
