INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1567","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n災害後、離れ離れになった（　）を捜す人が相次いだ。","options":["肉親","墜落","刺繍","心情"],"answer":"肉親","explanationKo":"문맥상 「肉親」가 가장 자연스럽다. 육친; 혈육라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1568","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）が進み、遠くの標識が見えにくくなった。","options":["待望","初版","全盛","近視"],"answer":"近視","explanationKo":"문맥상 「近視」가 가장 자연스럽다. 근시라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1569","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n受付で（　）を受け取り、胸につけて会場に入った。","options":["群集","内陸","名札","詐欺"],"answer":"名札","explanationKo":"문맥상 「名札」가 가장 자연스럽다. 명찰; 이름표라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1570","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n事故の影響で道路の一部が一時（　）された。","options":["捕獲","封鎖","納入","操縦"],"answer":"封鎖","explanationKo":"문맥상 「封鎖」가 가장 자연스럽다. 봉쇄; 차단라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1571","prompt":"「学校・研修などで定められた課程をすべて終えること。」という意味に最も近い語を選びなさい。","options":["修了","脚色","収支","平常"],"answer":"修了","explanationKo":"「修了」의 핵심 의미는 수료이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1575","prompt":"「連続する物事を分ける境目。また、仕事・期間などのひとまとまりが終わる節目。」という意味に最も近い語を選びなさい。","options":["展望","一変","収容","区切り"],"answer":"区切り","explanationKo":"「区切り」의 핵심 의미는 구분; 매듭; 한 단락이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1579","prompt":"「体内で血液を運ぶ管。動脈・静脈・毛細血管などがある。」という意味に最も近い語を選びなさい。","options":["突破","結束","血管","増進"],"answer":"血管","explanationKo":"「血管」의 핵심 의미는 혈관이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1581","prompt":"「小説・事実などを舞台・映画向けに作り変えること。また、事実に手を加えて話を面白く見せること。」という意味に最も近い語を選びなさい。","options":["凶作","脚色","金槌","お手上げ"],"answer":"脚色","explanationKo":"「脚色」의 핵심 의미는 각색; 윤색이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1582","prompt":"「布に色糸などを縫い込んで、模様・文字・絵を表すこと。また、その作品。」という意味に最も近い語を選びなさい。","options":["刺繍","必修","独創","重宝"],"answer":"刺繍","explanationKo":"「刺繍」의 핵심 의미는 자수이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','grammar',1,'〜とあっては','{"pattern":"〜とあっては","meaningKo":"〜라면","explanation":"〜とあっては는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"家族の安全に関わるとあっては、放置できない。","ko":"문맥에서 〜라면의 의미로 쓰였다."},{"ja":"責任者の要請とあっては、協力しないわけにはいかない。","ko":"이 문장도 〜라면의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','grammar',2,'〜ときている','{"pattern":"〜ときている","meaningKo":"게다가 〜한 상태다","explanation":"〜ときている는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"道は狭いうえに夜は暗いときている。","ko":"문맥에서 게다가 〜한 상태다의 의미로 쓰였다."},{"ja":"価格が高く、操作も複雑ときているため普及しにくい。","ko":"이 문장도 게다가 〜한 상태다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n家族の安全に関わる（　）、放置できない。","options":["〜を兼ねて","〜とあっては","〜を顧みず","〜ないものか"],"answer":"〜とあっては","explanationKo":"문맥상 〜라면를 나타내는 「〜とあっては」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
