INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-07','reading',1,'成果を別の場へ移す','{"passage":"ある場所の成功例を他へ応用することには、試行で得た知識を広く活用できることという効果が期待できる。ただし、条件の違いを無視すると同じ成果が出ないことにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、再現に必要な条件を分けて検証することが重要になる。","questions":[{"prompt":"「成果を別の場へ移す」について筆者が最も重視することは何か。","options":["再現に必要な条件を分けて検証すること","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"再現に必要な条件を分けて検証すること","explanationKo":"글쓴이는 再現に必要な条件を分けて検証すること 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["条件の違いを無視すると同じ成果が出ないこと","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"条件の違いを無視すると同じ成果が出ないこと","explanationKo":"주의할 점은 条件の違いを無視すると同じ成果が出ないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["試行で得た知識を広く活用できること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"試行で得た知識を広く活用できること","explanationKo":"ある場所の成功例を他へ応用すること에는 試行で得た知識を広く活用できること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
