INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1602","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n老朽化した建物は周辺の安全を確保したうえで（　）された。","options":["弾力","爆破","脚色","心情"],"answer":"爆破","explanationKo":"문맥상 「爆破」가 가장 자연스럽다. 폭파라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1608","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n駅前で投資商品の（　）を受けたが、その場では契約しなかった。","options":["勧誘","初版","全盛","一心"],"answer":"勧誘","explanationKo":"문맥상 「勧誘」가 가장 자연스럽다. 권유; 가입 권유; 모집라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1609","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n候補者は駅前で（　）演説を行った。","options":["栽培","抗争","強行","街頭"],"answer":"街頭","explanationKo":"문맥상 「街頭」가 가장 자연스럽다. 가두; 길거리라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1610","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n健康診断では血液だけでなく（　）の検査も行われた。","options":["暴露","寄贈","尿","破棄"],"answer":"尿","explanationKo":"문맥상 「尿」가 가장 자연스럽다. 소변; 오줌라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1612","prompt":"「人・物事を強く憎む感情。」という意味に最も近い語を選びなさい。","options":["弾力","憎しみ","刺繍","心情"],"answer":"憎しみ","explanationKo":"「憎しみ」의 핵심 의미는 미움; 증오이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1616","prompt":"「陶石などを高温で焼いて作る、白く硬く吸水性の低い焼き物。」という意味に最も近い語を選びなさい。","options":["磁器","初版","全盛","一心"],"answer":"磁器","explanationKo":"「磁器」의 핵심 의미는 자기; 도자기류이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1623","prompt":"「組織で、文書・備品・連絡・施設管理など幅広い日常事務を扱う仕事。」という意味に最も近い語を選びなさい。","options":["群集","内陸","兆し","庶務"],"answer":"庶務","explanationKo":"「庶務」의 핵심 의미는 서무; 일반 행정 업무이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1626","prompt":"「目の病気・視力などを診察・治療する医学分野。また、その診療科。」という意味に最も近い語を選びなさい。","options":["火花","防火","眼科","寒気"],"answer":"眼科","explanationKo":"「眼科」의 핵심 의미는 안과이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1627","prompt":"「商売・店などに客が多く集まり、非常に栄えること。」という意味に最も近い語を選びなさい。","options":["市街","繁盛","収支","平常"],"answer":"繁盛","explanationKo":"「繁盛」의 핵심 의미는 번창; 성업이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','grammar',1,'〜とみるや','{"pattern":"〜とみるや","meaningKo":"〜라고 보자마자","explanation":"〜とみるや는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"危険だとみるや、係員は直ちに入場を制限した。","ko":"문맥에서 〜라고 보자마자의 의미로 쓰였다."},{"ja":"相手が方針を変えたとみるや、各社は戦略を修正した。","ko":"이 문장도 〜라고 보자마자의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','grammar',2,'〜ならいざ知らず','{"pattern":"〜ならいざ知らず","meaningKo":"〜라면 몰라도","explanation":"〜ならいざ知らず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"子どもならいざ知らず、大人がその規則を知らないでは済まない。","ko":"문맥에서 〜라면 몰라도의 의미로 쓰였다."},{"ja":"一度ならいざ知らず、同じ誤りを繰り返すのは問題だ。","ko":"이 문장도 〜라면 몰라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n危険だ（　）、係員は直ちに入場を制限した。","options":["〜とみるや","〜ものと思われる","〜を余儀なくさせる","〜に先んじて"],"answer":"〜とみるや","explanationKo":"문맥상 〜라고 보자마자를 나타내는 「〜とみるや」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n子ども（　）、大人がその規則を知らないでは済まない。","options":["〜ものとして","〜をもって","〜にとどまらず","〜ならいざ知らず"],"answer":"〜ならいざ知らず","explanationKo":"문맥상 〜라면 몰라도를 나타내는 「〜ならいざ知らず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n天候（　）、説明会は予定どおり開催する。","options":["〜をもってしても","〜にまつわる","〜にかかわらず","〜ものなら"],"answer":"〜にかかわらず","explanationKo":"문맥상 〜와 관계없이를 나타내는 「〜にかかわらず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-08','reading',1,'中断後に再開する準備','{"passage":"作業を安全に中断できるようにすることには、担当や時間が変わっても続きから再開できることという効果が期待できる。ただし、結果だけ残すと次の判断根拠が分からないことにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、完了範囲と未解決事項と次の手順を記録することが重要になる。","questions":[{"prompt":"「中断後に再開する準備」について筆者が最も重視することは何か。","options":["完了範囲と未解決事項と次の手順を記録すること","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"完了範囲と未解決事項と次の手順を記録すること","explanationKo":"글쓴이는 完了範囲と未解決事項と次の手順を記録すること 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["結果だけ残すと次の判断根拠が分からないこと","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"結果だけ残すと次の判断根拠が分からないこと","explanationKo":"주의할 점은 結果だけ残すと次の判断根拠が分からないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["担当や時間が変わっても続きから再開できること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"担当や時間が変わっても続きから再開できること","explanationKo":"作業を安全に中断できるようにすること에는 担当や時間が変わっても続きから再開できること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-09','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1639","prompt":"「怪獣」の読み方として最も適切なものを選びなさい。","options":["かいじゅう","ぼうとう","えんがん","ニュアンス"],"answer":"かいじゅう","explanationKo":"「怪獣」는 「かいじゅう」라고 읽는다. 뜻은 괴수이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
