INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-09','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1684","prompt":"「長い間、実現・登場などを強く待ち望むこと。」という意味に最も近い語を選びなさい。","options":["全滅","負傷","待望","執着"],"answer":"待望","explanationKo":"「待望」의 핵심 의미는 대망; 오래 기다림이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-09','grammar',1,'〜にかかわらず','{"pattern":"〜にかかわらず","meaningKo":"〜와 관계없이","explanation":"〜にかかわらず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"年齢にかかわらず、意欲のある人を募集する。","ko":"문맥에서 〜와 관계없이의 의미로 쓰였다."},{"ja":"天候にかかわらず、説明会は予定どおり開催する。","ko":"이 문장도 〜와 관계없이의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-09','grammar',2,'〜を顧みず','{"pattern":"〜を顧みず","meaningKo":"〜을 돌보지 않고","explanation":"〜を顧みず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"救助隊は自らの危険を顧みず、現場へ向かった。","ko":"문맥에서 〜을 돌보지 않고의 의미로 쓰였다."},{"ja":"彼は周囲の反対を顧みず、改革を断行した。","ko":"이 문장도 〜을 돌보지 않고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-09','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n年齢（　）、意欲のある人を募集する。","options":["〜ものなら","〜をもってしても","〜にまつわる","〜にかかわらず"],"answer":"〜にかかわらず","explanationKo":"문맥상 〜와 관계없이를 나타내는 「〜にかかわらず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-09','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n救助隊は自らの危険（　）、現場へ向かった。","options":["〜を踏まえて","〜に言わせれば","〜を顧みず","〜ものの"],"answer":"〜を顧みず","explanationKo":"문맥상 〜을 돌보지 않고를 나타내는 「〜を顧みず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-09','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n黙っていれば疑われずに済んだ（　）、余計な説明を加えた。","options":["〜にしたところで","〜ものを","〜ないものか","〜を経て"],"answer":"〜ものを","explanationKo":"문맥상 〜했으면 좋았을 텐데를 나타내는 「〜ものを」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-09','reading',1,'学習順序を調整する','{"passage":"学ぶ項目の順序を組み替えることには、基礎知識を後の内容に結び付けやすくなることという効果が期待できる。ただし、難易度だけで並べると実際の必要性を外すことにも注意が必要である。目的や対象を明確にし、実施後の結果を確認できる形にしておかなければならない。したがって、前提知識と使用頻度の両方から順序を決めることが重要になる。","questions":[{"prompt":"「学習順序を調整する」について筆者が最も重視することは何か。","options":["前提知識と使用頻度の両方から順序を決めること","一度決めた方法を変えないこと","対象を限定せずに進めること","結果を確認せず終了すること"],"answer":"前提知識と使用頻度の両方から順序を決めること","explanationKo":"글쓴이는 前提知識と使用頻度の両方から順序を決めること 것이 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["難易度だけで並べると実際の必要性を外すこと","効果が必ず失われること","目的を決める必要がないこと","記録すると判断できなくなること"],"answer":"難易度だけで並べると実際の必要性を外すこと","explanationKo":"주의할 점은 難易度だけで並べると実際の必要性を外すこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["基礎知識を後の内容に結び付けやすくなること","実施後の確認は不要である","対象は曖昧なままでよい","方法は結果と関係なく固定すべきだ"],"answer":"基礎知識を後の内容に結び付けやすくなること","explanationKo":"学ぶ項目の順序を組み替えること에는 基礎知識を後の内容に結び付けやすくなること라는 효과가 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
